return ['domain'=>'nashenski-commerce','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'bg_BG','project-id-version'=>'Nashenski Commerce 0.10.0','pot-creation-date'=>'2026-10-09 17:19+0000','po-revision-date'=>'2026-10-09 17:19+0000','messages'=>['If you like %1$s please leave us a %2$s rating. A huge thanks in advance!'=>'Ако харесвате %1$s, оставете ни оценка %2$s. Благодарим ви предварително!','Nashenski Commerce'=>'Нашенски Комерс','five star'=>'пет звезди','BOX NOW Delivery'=>'Доставка с BOX NOW','Send to'=>'Изпращане до','Send From'=>'Изпращане от','Warehouse/Automat'=>'Склад/автомат','Automat'=>'Автомат','Total price'=>'Обща цена','Allow returns'=>'Разрешаване на връщане','Update shipment status'=>'Обновяване на статуса на пратката','Generate label'=>'Създаване на товарителница','Delete label'=>'Изтриване на товарителницата','Label'=>'Товарителница','Selected'=>'Избрано','Choose'=>'Избери','Label data'=>'Данни за товарителницата','Shipment status'=>'Статус на пратката','Box size'=>'Размер на кутията','Automatically pack products to boxes'=>'Автоматично разпределяне на продуктите в кутии','Small Box'=>'Малка кутия','Medium Box'=>'Средна кутия','Large Box'=>'Голяма кутия','Pack'=>'Пакет','Add Pack'=>'Добавяне на пакет','Remove Pack'=>'Премахване на пакет','Weight'=>'Тегло','Price'=>'Цена','Name'=>'Име','Cash on delivery orders cannot be split into multiple packets.'=>'Поръчки с наложен платеж не могат да се разделят на няколко пакета.','BOX NOW did not answer. Check the connection settings and try again.'=>'BOX NOW не отговори. Проверете настройките за връзка и опитайте отново.','You do not have permission to perform this action.'=>'Нямате права за това действие.','This link has expired. Reload the order page and try again.'=>'Връзката е изтекла. Презаредете страницата на поръчката и опитайте отново.','Nashenski Commerce changelog'=>'Промени в Нашенски Комерс','Changelog'=>'Промени','Sorry, you are not allowed to view this page.'=>'Нямате достъп до тази страница.','CVC Delivery'=>'Доставка с CVC','Update label'=>'Обновяване на товарителницата','Default'=>'По подразбиране','Delivery is payed by'=>'Доставката се плаща от','Cash on delivery'=>'Наложен платеж','Pack count'=>'Брой пакети','Shipment type'=>'Вид на пратката','Other'=>'Друго','bl. vh. et.'=>'бл. вх. ет.','Street number'=>'Номер на улица','Street/Quarter'=>'Улица/квартал','Office'=>'Офис','Address'=>'Адрес','Delivery type'=>'Вид доставка','Buyer'=>'Купувач','Sender'=>'Подател','Contract'=>'Договор','Fixed price'=>'Фиксирана цена','Copy Label Data'=>'Копиране на данните за товарителницата','You just copied the label data used for the cvc API.'=>'Копирахте данните за товарителницата, изпратени към API на CVC.','Time:'=>'Час:','Event:'=>'Събитие:','Details:'=>'Подробности:','Review and test'=>'Преглед и тест','Declared value'=>'Обявена стойност','Description'=>'Описание','Econt Delivery'=>'Доставка с Еконт','Block'=>'Блок','Entrance'=>'Вход','Floor'=>'Етаж','Apartment'=>'Апартамент','Street number is required.'=>'Номерът на улицата е задължителен.','Fill in at least one of block, entrance, floor or apartment.'=>'Попълнете поне едно от: блок, вход, етаж или апартамент.','You just copied the label data used for the Econt API.'=>'Копирахте данните за товарителницата, изпратени към API на Еконт.','Invoice number'=>'Номер на фактура','Partial delivery'=>'Частична доставка','Length'=>'Дължина','Width'=>'Ширина','Height'=>'Височина','Document'=>'Документ','Pallet'=>'Палет','Cargo'=>'Товар','Document-Pallet'=>'Документ-палет','Enable VIES validation'=>'Проверка във VIES','Validate the VAT number with the European VIES system or only with regex.'=>'Проверка на ДДС номера в европейската система VIES или само по формат.','Tax Classes for Digital Goods'=>'Данъчни класове за цифрови стоки','This option tells the plugin which of your tax classes are for digital goods. This affects the taxable location of the user as of 1st Jan 2015.'=>'Показва кои данъчни класове са за цифрови стоки. От 1 януари 2015 г. това определя мястото на облагане според клиента.','VAT number'=>'ДДС номер','EU VAT'=>'ДДС в ЕС','This order is out of scope for EU VAT.'=>'Тази поръчка е извън обхвата на ДДС в ЕС.','Validation was not possible'=>'Проверката не беше възможна','IP Address'=>'IP адрес','Unknown'=>'Неизвестно','IP Country'=>'Държава по IP','(self-declared)'=>'(декларирана от клиента)','Billing Country'=>'Държава за фактуриране','You do not have permission to do this.'=>'Нямате права за това.','Add at least one column.'=>'Добавете поне една колона.','Give the export a name.'=>'Дайте име на експорта.','Excel files need the PHP Zip extension, which this server does not have. Choose CSV instead.'=>'Файловете за Excel изискват PHP разширението Zip, което липсва на този сървър. Изберете CSV.','New export'=>'Нов експорт','Ready-made'=>'Готови','Saved exports'=>'Запазени експорти','Add'=>'Добавяне','Remove'=>'Премахване','Move up'=>'Нагоре','Move down'=>'Надолу','Column heading'=>'Заглавие на колоната','No columns yet. Add fields from the list.'=>'Още няма колони. Добавете полета от списъка.','Saved.'=>'Запазено.','Deleted.'=>'Изтрито.','Delete this saved export?'=>'Да се изтрие ли този запазен експорт?','First %1$d of %2$d rows. File: %3$s'=>'Първите %1$d от %2$d реда. Файл: %3$s','Nothing matches these filters.'=>'Няма записи по тези филтри.','Something went wrong. Please try again.'=>'Нещо се обърка. Опитайте отново.','Order meta key, for example _billing_company_eik'=>'Мета ключ на поръчката, например _billing_company_eik','Order meta'=>'Мета данни на поръчката','Other shipping'=>'Друга доставка','Custom export'=>'Собствен експорт','Build your own file: choose the records, the columns and their order, the format and the file name. Preview it, save it for next month and download it.'=>'Създайте свой файл: изберете записите, колоните и реда им, формата и името на файла. Прегледайте го, запазете го за следващия месец и го изтеглете.','Start from'=>'Започнете от','Delete this saved export'=>'Изтриване на този запазен експорт','What to export'=>'Какво да се експортира','Orders'=>'Поръчки','One row per order'=>'По един ред за поръчка','Products sold'=>'Продадени продукти','One row per product line'=>'По един ред за всеки продукт в поръчката','Documents'=>'Документи','One row per invoice, credit note or order document'=>'По един ред за фактура, кредитно известие или документ за продажба','Which records'=>'Кои записи','From'=>'От','To'=>'До','By'=>'По','order date'=>'дата на поръчка','payment date'=>'дата на плащане','completion date'=>'дата на изпълнение','This month'=>'Този месец','Last month'=>'Миналия месец','This year'=>'Тази година','Last year'=>'Миналата година','Order status'=>'Статус на поръчката','Payment method'=>'Начин на плащане','Courier'=>'Куриер','Document type'=>'Вид документ','Only orders with a company invoice'=>'Само поръчки с фактура на фирма','Leave a list empty to include everything.'=>'Оставете списък празен, за да включите всичко.','Columns'=>'Колони','Find a field'=>'Търсене на поле','Add an order meta field'=>'Добавяне на мета поле на поръчката','Drag to reorder. Click a heading to rename it.'=>'Плъзнете, за да промените реда. Щракнете върху заглавие, за да го преименувате.','File'=>'Файл','Separator'=>'Разделител','Semicolon ;'=>'Точка и запетая ;','Comma ,'=>'Запетая ,','Tab'=>'Табулация','Vertical bar |'=>'Вертикална черта |','Encoding'=>'Кодировка','UTF-8 for Excel'=>'UTF-8 за Excel','Windows-1251 (older accounting software)'=>'Windows-1251 (по-стар счетоводен софтуер)','Decimal mark'=>'Десетичен знак','Dates'=>'Дати','File name'=>'Име на файла','Root element'=>'Основен елемент','Row element'=>'Елемент за ред','In the file name, {from}, {to}, {today} and {source} are replaced with the dates and the record type.'=>'В името на файла {from}, {to}, {today} и {source} се заменят с датите и вида на записите.','Headings in the first row'=>'Заглавия на първия ред','Save as'=>'Запазване като','For example: Monthly sales for the accountant'=>'Например: Месечни продажби за счетоводителя','Save export'=>'Запазване на експорта','Preview'=>'Преглед','Download file'=>'Изтегляне на файла','Getting started'=>'Първи стъпки','How to use it'=>'Как се използва','Support'=>'Поддръжка','Ask questions and report problems in the %s.'=>'Задавайте въпроси и съобщавайте за проблеми във %s.','support forum'=>'форума за поддръжка','WooCommerce > Settings > Shipping'=>'WooCommerce > Настройки > Доставка','In %s, turn on the couriers you work with, invoices and the customer checks you need, and save.'=>'В %s включете куриерите, с които работите, фактурите и нужните проверки на клиенти и запазете.','Overview'=>'Общ преглед','In %s, enter the login or API keys the courier gave you for online shops.'=>'В %s въведете данните за вход или API ключовете, които куриерът Ви е дал за онлайн магазини.','Couriers'=>'Куриери','In %s, add the courier shipping methods to your zone: one method per delivery type (to an office, to a locker, to an address).'=>'В %s добавете методите за доставка на куриерите към вашата зона: по един метод за всеки вид доставка (до офис, до автомат, до адрес).','In %s, choose the countries, the checkout fields and the look of the shipping options.'=>'В %s изберете държавите, полетата при плащане и вида на опциите за доставка.','Checkout'=>'Плащане','In %s, fill in your company details and choose when invoices are made. Add your logo for the PDF documents.'=>'В %s попълнете данните на фирмата си и изберете кога да се издават фактури. Добавете логото си за PDF документите.','Every month, create the NRA audit file in %s and submit it by the 15th, or have it emailed to your accountant.'=>'Всеки месец създавайте одиторския файл за НАП в %s и го подавайте до 15-о число или нека се изпраща на счетоводителя Ви по имейл.','Exports'=>'Експорти','Couriers and shipping methods'=>'Куриери и методи за доставка','Turn a courier on in %s. Its page appears in Couriers and its methods can be added to your shipping zones.'=>'Включете куриер в %s. Страницата му се появява в „Куриери“, а методите му могат да се добавят към зоните за доставка.','Add one method per delivery type to a zone: to an office, to a parcel locker and to an address. BOX NOW has one method, for its lockers.'=>'Добавете към зоната по един метод за всеки вид доставка: до офис, до автомат за пратки и до адрес. BOX NOW има един метод, за своите автомати.','Enter the login in %s. Demo logins only reach the courier\'s test system, where nothing is really shipped. If the courier refuses a login, the courier page says so.'=>'Въведете данните за вход в %s. Демо данните стигат само до тестовата система на куриера, където нищо не се изпраща наистина. Ако куриерът откаже входа, страницата на куриера го показва.','Without a login, customers can still choose: Econt offices and lockers from Econt\'s list, Speedy offices on Speedy\'s map, Pigeon Express offices and lockers and BOX NOW lockers from the lists they publish. CVC offices need a login. Waybills always need one.'=>'И без вход клиентите могат да избират: офиси и автомати на Еконт от списъка на Еконт, офиси на Спиди от картата на Спиди, офиси и автомати на Pigeon Express и автомати на BOX NOW от публикуваните им списъци. Офисите на CVC изискват вход. Товарителниците винаги изискват вход.','Cities, offices and lockers are kept on your site and refreshed once a week. "Reload offices and cities" on a courier page refreshes them at once.'=>'Населените места, офисите и автоматите се пазят на сайта Ви и се обновяват веднъж седмично. „Презареждане на офиси и населени места“ на страницата на куриера ги обновява веднага.','Shipping prices'=>'Цени за доставка','With a login, the courier calculates each price with your contract. Without one, or when the courier does not answer, the courier\'s public price list is used. You can edit it on the courier page and compare it with the courier website.'=>'С вход куриерът изчислява всяка цена по Вашия договор. Без вход или когато куриерът не отговаря, се използва публичната му ценова листа. Можете да я редактирате на страницата на куриера и да я сравните със сайта на куриера.','Each shipping method in a zone can have a free shipping amount and a fixed price.'=>'Всеки метод за доставка в зона може да има сума за безплатна доставка и фиксирана цена.','When a courier publishes new prices, a notice says so. Save that courier\'s prices or press Dismiss.'=>'Когато куриер публикува нови цени, се появява известие. Запазете цените на този куриер или натиснете „Скриване“.','Works with the classic checkout, the block checkout and checkout pages made with a page builder, including step-by-step checkouts.'=>'Работи с класическото плащане, блоковото плащане и страници за плащане, създадени с конструктор, включително плащане на стъпки.','When the customer picks a courier, they choose an office, a locker or an address right under it, from a list or on the courier\'s map. Until then the option says "Complete the fields to calculate".'=>'Когато клиентът избере куриер, точно под него избира офис, автомат или адрес, от списък или на картата на куриера. Дотогава опцията показва „Попълнете данните за изчисляване“.','In %s > Checkout fields you set the order, Required, Optional or Hidden and the width of every field, and add your own fields.'=>'В %s > Полета при плащане задавате реда, задължително, незадължително или скрито и ширината на всяко поле, и добавяте свои полета.','"Company invoice fields" adds "I want an invoice for a company" with company name, EIK, VAT number, MOL, town and address.'=>'„Полета за фактура на фирма“ добавя „Искам фактура на фирма“ с име на фирмата, ЕИК, ДДС номер, МОЛ, населено място и адрес.','"Shipping options look" sets cards or the plain look of your theme, colours, borders, corners and spacing. Empty settings follow your design tokens or theme.'=>'„Вид на опциите за доставка“ задава карти или обикновения вид на темата, цветове, рамки, ъгли и разстояния. Празните настройки следват дизайн токените или темата Ви.','Waybills, couriers and order statuses'=>'Товарителници, куриери и статуси на поръчките','Open an order to create, update, print or cancel its waybill in the courier box.'=>'Отворете поръчка, за да създадете, промените, отпечатате или анулирате товарителницата ѝ в полето на куриера.','In the "Order actions" box of an order, and in the bulk actions of the orders list: "Create waybill" makes the waybill from the customer\'s choices, "Request a courier" books a pickup with Econt or Speedy for all the chosen waybills, "Check the shipment now" reads the status from the courier.'=>'В полето „Действия с поръчката“ и в груповите действия на списъка с поръчки: „Създай товарителница“ създава товарителница по избора на клиента, „Заяви куриер“ заявява вземане от Еконт или Спиди за всички избрани товарителници, „Провери пратката сега“ прочита статуса от куриера.','Econt courier requests skip weekends and holidays by themselves. Speedy picks the next possible day.'=>'Заявките за куриер на Еконт сами прескачат почивни и празнични дни. Спиди избира следващия възможен ден.','"Generate label after checkout" on a courier page makes the waybill as soon as an order is placed.'=>'„Създаване на товарителница след поръчка“ на страницата на куриера създава товарителницата веднага щом поръчката е направена.','In %s > Waybills and order statuses: put the order number on the waybill, and choose the status orders get when the parcel is delivered or goes back to you. Open orders are checked every hour.'=>'В %s > Товарителници и статуси на поръчките: добавете номера на поръчката в товарителницата и изберете статуса, който поръчките получават, когато пратката е доставена или се връща при Вас. Отворените поръчки се проверяват всеки час.','Customers see "Track your parcel" with the waybill number on their order page, and get it in the order emails.'=>'Клиентите виждат „Проследете пратката си“ с номера на товарителницата на страницата на поръчката си и го получават в имейлите за поръчката.','Invoices and documents'=>'Фактури и документи','The order document is made for every order. Invoices are made as set in "When to generate invoices?", and credit notes for refunds.'=>'Документът за продажба се създава за всяка поръчка. Фактурите се създават според „Кога да се издават фактури?“, а кредитните известия при връщане на суми.','To make an invoice by hand, open the order and use "Make invoice" in the PDF Files box. You can change the number; the next automatic number continues after it.'=>'За фактура на ръка отворете поръчката и използвайте „Издай фактура“ в полето „PDF файлове“. Можете да смените номера; следващият автоматичен номер продължава след него.','The look of the PDF files (logo, colours, font, spacing) is in %s > PDF appearance. Every document is made in Bulgarian and in English.'=>'Видът на PDF файловете (лого, цветове, шрифт, разстояния) е в %s > Вид на PDF документите. Всеки документ се създава на български и на английски.','Copies can go to your accountant by email, and the monthly NRA audit file too.'=>'Копията могат да се изпращат на счетоводителя Ви по имейл, както и месечният одиторски файл за НАП.','NRA audit file and exports'=>'Одиторски файл за НАП и експорти','%s has the NRA audit file (Ordinance N-18), the invoice archive and the Microinvest Delta file for a chosen month. The audit file is checked against the NRA schema and has no order limit.'=>'%s съдържа одиторския файл за НАП (Наредба Н-18), архива с фактури и файла за Microinvest Delta за избран месец. Одиторският файл се проверява спрямо схемата на НАП и няма ограничение за броя поръчки.','The custom export takes orders, products sold or documents, with your filters, columns and order, as CSV, Excel, JSON or XML. Save an export to run it again next month.'=>'Собственият експорт взема поръчки, продадени продукти или документи, с Вашите филтри, колони и подредба, като CSV, Excel, JSON или XML. Запазете експорта, за да го пуснете отново следващия месец.','EU withdrawal function'=>'Функция за отказ (ЕС)','Turn it on in %s > EU withdrawal function. A "Withdraw from contract here" link appears at the bottom of every page, on each order in My Account and in the order emails.'=>'Включете я в %s > Функция за отказ (ЕС). Връзката „откажете се от договора тук“ се появява в долната част на всяка страница, при всяка поръчка в „Моят профил“ и в имейлите за поръчката.','Place the link yourself with the shortcode [nashenski_withdrawal_link] (button="yes" makes it a button).'=>'Поставете връзката сами с краткия код [nashenski_withdrawal_link] (button="yes" я прави бутон).','Requests show in the orders list ("Withdrawal" column) and on the order, with everything the customer submitted.'=>'Заявките се виждат в списъка с поръчки (колона „Отказ“) и в поръчката, с всичко, което клиентът е подал.','Customer checks'=>'Проверки на клиенти','nekorekten.com, Connectix and NepoStop tell you whether a phone number has a history of refused parcels. Nashenski Commerce can show a warning on the order and hide cash on delivery for such customers.'=>'nekorekten.com, Connectix и NepoStop показват дали един телефонен номер има история на отказани пратки. Нашенски Комерс може да покаже предупреждение в поръчката и да скрие наложения платеж за такива клиенти.','Moving from another plugin'=>'Преминаване от друг плъгин','Nashenski Commerce imports from Bulgarisation for WooCommerce, the mreja.net plugins (Econt Express, BOX NOW Delivery, Ordinance N-18), Drusoft Shipping for Econt and for Speedy, Econt Delivery and Speedy Shipping.'=>'Нашенски Комерс внася данни от Bulgarisation for WooCommerce, плъгините на mreja.net (Еконт Експрес, BOX NOW Delivery, Наредба Н-18), Drusoft Shipping за Еконт и за Спиди, Econt Delivery и Speedy Shipping.','It takes over the courier logins, sender details, the waybill numbers of your orders, the shipping zone methods and, from the N-18 plugin, the company details and document numbers. Then the old plugin is switched off. Its own data stays in the database.'=>'Взема данните за вход към куриерите, данните на подателя, номерата на товарителниците на поръчките, методите в зоните за доставка, а от плъгина за Н-18 и данните на фирмата и номерата на документите. След това старият плъгин се изключва. Неговите данни остават в базата данни.','Econt Delivery and Drusoft Shipping for Econt use a different Econt key: enter your Econt username and password after the import.'=>'Econt Delivery и Drusoft Shipping за Еконт използват друг ключ на Еконт: след внасянето въведете потребителското си име и паролата за Еконт.','When something does not work'=>'Когато нещо не работи','"Nothing found" under a courier: check the login on the courier page. In BOX NOW demo mode there are only two test lockers, both in Sofia.'=>'„Нищо не е намерено“ под куриер: проверете входа на страницата на куриера. В демо режим на BOX NOW има само два тестови автомата, и двата в София.','No courier options at checkout: add the methods to the shipping zone of the customer\'s address and give your products a weight.'=>'Няма опции за куриер при плащане: добавете методите към зоната за доставка на адреса на клиента и задайте тегло на продуктите.','"Complete the fields to calculate" does not go away: the customer has not chosen an office, a locker or an address yet.'=>'„Попълнете данните за изчисляване“ не изчезва: клиентът още не е избрал офис, автомат или адрес.','No documents: turn on "Invoices and N-18" in Overview and check "When to generate documents?" in Documents.'=>'Няма документи: включете „Фактури и Н-18“ в „Общ преглед“ и проверете „Кога да се създават документите?“ в „Документи“.','Bulgarisation for WooCommerce'=>'Bulgarisation for WooCommerce','These plugins are installed or left data on your site. Import takes over what Nashenski Commerce can use and switches the plugin off.'=>'Тези плъгини са инсталирани или са оставили данни на сайта Ви. Внасянето взема това, което Нашенски Комерс може да използва, и изключва плъгина.','Imported on %s'=>'Внесено на %s','Import and switch off'=>'Внеси и изключи','%d setting changed.'=>'Променена е %d настройка.' . "\0" . 'Променени са %d настройки.','Recommended settings'=>'Препоръчителни настройки','Settings that suit most Bulgarian stores. Tick the ones you want and apply them; nothing else changes.'=>'Настройки, подходящи за повечето български магазини. Отметнете желаните и ги приложете; нищо друго не се променя.','Apply'=>'Прилагане','Setting'=>'Настройка','Now'=>'Сега','Recommended'=>'Препоръчано','Why'=>'Защо','Already set'=>'Вече е зададено','Apply recommended settings'=>'Прилагане на препоръчителните настройки','All recommended settings are in place.'=>'Всички препоръчителни настройки са приложени.','Econt Express shipping method (mreja.net)'=>'Метод за доставка Еконт Експрес (mreja.net)','BOX NOW Delivery (mreja.net)'=>'BOX NOW Delivery (mreja.net)','Ordinance N-18 light regime (mreja.net)'=>'Наредба Н-18 облекчен режим (mreja.net)','Change Speedy and Econt Shipping Methods (mreja.net)'=>'Бутони за методите за доставка на Спиди и Еконт (mreja.net)','Drusoft Shipping for Econt'=>'Drusoft Shipping за Еконт','Drusoft Shipping for Speedy'=>'Drusoft Shipping за Спиди','Econt Delivery (Econt)'=>'Econt Delivery (Еконт)','Speedy Shipping (Speedy)'=>'Speedy Shipping (Спиди)','WooCommerce Speedy Offices'=>'WooCommerce Speedy Offices','Imported from %s:'=>'Внесено от %s:','Nashenski Commerce can take over the data of %s, then switch it off.'=>'Нашенски Комерс може да поеме данните на %s и след това да ги изключи.','Review and import'=>'Преглед и внасяне','Dismiss'=>'Скриване','The Econt key of that plugin works only with Econt\'s "Deliver with Econt" service. Enter your Econt username and password in Couriers > Econt.'=>'Ключът на Еконт от този плъгин работи само с услугата „Достави с Еконт“. Въведете потребителското си име и паролата за Еконт в Куриери > Еконт.','%d setting'=>'%d настройка' . "\0" . '%d настройки','%d order waybill'=>'%d товарителница на поръчка' . "\0" . '%d товарителници на поръчки','%d shipping zone method'=>'%d метод в зона за доставка' . "\0" . '%d метода в зони за доставка','%d document number'=>'%d номер на документ' . "\0" . '%d номера на документи','%d order keeps everything the old plugin saved on it (see "From earlier plugins" on the order)'=>'%d поръчка запазва всичко, което старият плъгин е записал в нея (вижте „От предишни плъгини“ в поръчката)' . "\0" . '%d поръчки запазват всичко, което старият плъгин е записал в тях (вижте „От предишни плъгини“ в поръчката)','%s was switched off.'=>'%s беше изключен.','From earlier plugins'=>'От предишни плъгини','What the earlier plugins saved on this order, kept when their data was imported.'=>'Това, което предишните плъгини са записали в тази поръчка, запазено при внасянето на данните им.','Order document'=>'Документ за продажба','Invoice'=>'Фактура','Credit note'=>'Кредитно известие','Cancelled order document'=>'Документ за отказана поръчка','To an office'=>'До офис','To a parcel locker'=>'До автомат за пратки','To an address'=>'До адрес','Mathematically impossible prices'=>'Математически невъзможни цени','Preparing...'=>'Подготовка...','Not started.'=>'Не е стартирано.','Scan products'=>'Сканиране на продуктите','Scanning...'=>'Сканиране...','An error occurred during scanning.'=>'Възникна грешка при сканирането.','AJAX error during scanning.'=>'AJAX грешка при сканирането.','Scanning finished.'=>'Сканирането приключи.','Scanning... page %1$s of %2$s'=>'Сканиране... страница %1$s от %2$s','Checked: %1$s | Problematic: %2$s'=>'Проверени: %1$s | Проблемни: %2$s','Fix all'=>'Поправяне на всички','Fixing...'=>'Поправяне...','Fix'=>'Поправяне','Edit'=>'Редактиране','Problematic'=>'Проблемна','Fixed'=>'Поправена','Missing target price'=>'Липсва целева цена','AJAX error'=>'AJAX грешка','Error'=>'Грешка','No problematic prices found.'=>'Няма проблемни цени.','No problematic prices remain.'=>'Не са останали проблемни цени.','There are no rows to fix.'=>'Няма редове за поправяне.','Fixing all... %1$s / %2$s'=>'Поправяне на всички... %1$s / %2$s','Fixed: %1$s | Not fixed: %2$s'=>'Поправени: %1$s | Непоправени: %2$s','You do not have permission to access this page.'=>'Нямате достъп до тази страница.','This tool scans products and shows only problematic prices.'=>'Този инструмент сканира продуктите и показва само проблемните цени.','You can learn more about this problem <a target="_blank" href="%s">here</a>.'=>'Повече за този проблем можете да прочетете <a target="_blank" href="%s">тук</a>.','Store setting:'=>'Настройка на магазина:','Prices are entered including tax'=>'Цените се въвеждат с включен данък','Prices are entered excluding tax'=>'Цените се въвеждат без данък','This check is mainly applicable when prices are entered including tax.'=>'Тази проверка има смисъл главно когато цените се въвеждат с включен данък.','ID'=>'ID','Product'=>'Продукт','Type'=>'Вид','SKU'=>'Код (SKU)','Field'=>'Поле','Entered price'=>'Въведена цена','Tax'=>'Данък','Nearest'=>'Най-близка','Down'=>'Надолу','Up'=>'Нагоре','Status'=>'Статус','Actions'=>'Действия','You do not have permission.'=>'Нямате права.','Invalid data.'=>'Невалидни данни.','The product was not found.'=>'Продуктът не е намерен.','Regular price'=>'Редовна цена','Sale price'=>'Промоционална цена','The price is no longer problematic.'=>'Цената вече не е проблемна.','The target price no longer matches.'=>'Целевата цена вече не съвпада.','The price was fixed.'=>'Цената е поправена.','The sale price was cleared because it was greater than or equal to the regular price.'=>'Промоционалната цена е изчистена, защото беше по-голяма или равна на редовната.','The sale price was adjusted to %s so it stays below the regular price.'=>'Промоционалната цена е променена на %s, за да остане под редовната.','Import finished: %1$d settings, %2$d shipping method settings, %3$d shipping zone methods, %4$d order shipping lines and %5$d order data rows.'=>'Импортирането приключи: %1$d настройки, %2$d настройки на методи за доставка, %3$d метода в зони за доставка, %4$d реда за доставка в поръчки и %5$d реда с данни на поръчки.','Accountant Document Copies'=>'Копия на документи за счетоводителя','This email sends invoice and credit notice copies to the accountant.'=>'Този имейл изпраща копия на фактурите и кредитните известия до счетоводителя.','Document Copy'=>'Копие на документ','[{site_title}]: Document copy for order #{order_number}'=>'[{site_title}]: Копие на документ за поръчка #{order_number}','Please find attached the document copies for order #%s.'=>'Прикачени са копията на документите за поръчка #%s.','Regenerate PDF\'s'=>'Повторно създаване на PDF файловете','%s order documents were regenerated.'=>'Документите на %s поръчка са създадени отново.' . "\0" . 'Документите на %s поръчки са създадени отново.','Invoice PDF'=>'PDF на фактурата','Invoice Copy PDF'=>'PDF на копието на фактурата','Refunded Invoice PDF'=>'PDF на кредитното известие','Refunded Invoice Copy PDF'=>'PDF на копието на кредитното известие','English'=>'English','Generate Invoice'=>'Създаване на фактура','The invoice number must be 1 to 10 digits.'=>'Номерът на фактурата трябва да е от 1 до 10 цифри.','Number %s is already used by another order. Choose another invoice number.'=>'Номер %s вече е използван от друга поръчка. Изберете друг номер на фактурата.','EN'=>'EN','Order'=>'Поръчка','Invoice Copy'=>'Копие на фактура','Refunded Order'=>'Възстановена поръчка','Refunded Invoice'=>'Кредитно известие','Refunded Invoice Copy'=>'Копие на кредитно известие','Pro forma'=>'Проформа','PDF Files'=>'PDF файлове','Make invoice'=>'Издай фактура','Uses the PDF look you set under Documents. Saves the order too.'=>'Използва вида на PDF, зададен в Документи. Запазва и поръчката.','Pigeon Express'=>'Pigeon Express','Locker'=>'Шкафче','You just copied the label data used for the Pigeon Express API.'=>'Копирахте данните за товарителницата, изпратени към API на Pigeon Express.','Reference number'=>'Референтен номер','Tracking codes'=>'Кодове за проследяване','Street or quarter'=>'Улица или квартал','Return at my expense'=>'Връщане за моя сметка','Note for courier'=>'Бележка за куриера','On'=>'Включено','Off'=>'Изключено','Required'=>'Задължително','Optional'=>'Незадължително','Hidden'=>'Скрито','Customer countries'=>'Държави на клиентите','Every order is for Bulgaria and customers do not see the country field.'=>'Всяка поръчка е за България и клиентите не виждат полето за държава.','Bulgaria only'=>'Само България','Bulgaria, Greece and Romania'=>'България, Гърция и Румъния','WooCommerce settings'=>'Настройки на WooCommerce','Courier logos at checkout'=>'Лога на куриерите при плащане','Customers recognise the courier at a glance.'=>'Клиентите разпознават куриера от пръв поглед.','Transliterate addresses'=>'Транслитерация на адресите','Couriers find Bulgarian addresses typed in Latin letters.'=>'Куриерите откриват български адреси, написани на латиница.','Bulgarian addresses in Cyrillic'=>'Българските адреси на кирилица','Cyrillic in Bulgaria, Latin abroad'=>'Кирилица в България, латиница в чужбина','Phone field'=>'Поле за телефон','Couriers call or text the customer before delivery.'=>'Куриерите се обаждат или пишат на клиента преди доставка.','Postcode field'=>'Поле за пощенски код','Bulgarian couriers deliver by city and office, so the postcode should not stop an order.'=>'Българските куриери доставят по населено място и офис, затова пощенският код не бива да спира поръчка.','Store currency'=>'Валута на магазина','Bulgaria uses the euro since 1 January 2026.'=>'България използва еврото от 1 януари 2026 г.','Currency position'=>'Позиция на валутата','Prices read the Bulgarian way: 12,50 €.'=>'Цените се изписват по български: 12,50 €.','Left'=>'Отляво','Right'=>'Отдясно','Left with space'=>'Отляво с интервал','Right with space'=>'Отдясно с интервал','Decimal separator'=>'Десетичен разделител','Bulgarian number format.'=>'Български формат на числата.','Thousand separator'=>'Разделител за хилядите','Space'=>'Интервал','None'=>'Без','Prices entered with tax'=>'Цени, въведени с данък','Prices in Bulgaria are shown and entered with VAT included.'=>'В България цените се показват и въвеждат с включен ДДС.','Yes'=>'Да','No'=>'Не','(not set)'=>'(не е зададено)','Help'=>'Помощ','Enable'=>'Включване','Turn on documents in the Overview to also get the NRA audit file, the invoice archive and the Microinvest Delta file here.'=>'Включете документите в Общ преглед, за да имате тук и одиторския файл за НАП, архива с фактури и файла за Microinvest Delta.','Connected to %s. Prices and labels use your account.'=>'Свързано с %s. Цените и товарителниците използват вашия профил.','Reload offices and cities'=>'Презареждане на офиси и населени места','Downloads the latest cities, offices and lockers (and your profile) from the courier. They also update by themselves once a week.'=>'Изтегля най-новите населени места, офиси и автомати (и вашия профил) от куриера. Те се обновяват и сами веднъж седмично.','Offices and cities will be downloaded again the next time they are needed.'=>'Офисите и населените места ще бъдат изтеглени отново, когато потрябват.','New published prices were found for %s. Open the courier, press "Check the courier website" and decide whether to use them.'=>'Открити са нови публикувани цени за %s. Отворете куриера, натиснете „Проверка в сайта на куриера“ и решете дали да ги използвате.','Public prices'=>'Публични цени','Used to price orders when this courier is not connected or does not answer, so customers can always order. The built-in prices come from the %1$s (valid from %2$s). Edit them, or let Nashenski Commerce check the courier website for newer prices.'=>'Използват се за цените на поръчките, когато куриерът не е свързан или не отговаря, за да могат клиентите винаги да поръчат. Вградените цени са от %1$s (в сила от %2$s). Редактирайте ги или оставете Нашенски Комерс да провери сайта на куриера за по-нови цени.','courier\'s published price list'=>'публикувания ценоразпис на куриера','unknown'=>'неизвестно','Use public prices'=>'Публични цени','Price orders with this list when there is no working courier login'=>'Цените на поръчките се изчисляват по този ценоразпис, когато няма работещ вход в куриера','Price list'=>'Ценоразпис','To a locker'=>'До автомат','Up to (kg)'=>'До (кг)','Remove row'=>'Премахване на реда','Heavier: base'=>'По-тежки: основна цена','+ per kg above the last row'=>'+ за кг над последния ред','Add row'=>'Добавяне на ред','Prices include VAT'=>'Цените са с ДДС','Extra surcharge (fuel, toll) %'=>'Допълнителна такса (гориво, пътна такса) %','Cash on delivery fee %'=>'Такса за наложен платеж %','at least'=>'най-малко','Valid from'=>'В сила от','Check the courier website'=>'Проверка в сайта на куриера','Restore the built-in prices'=>'Възстановяване на вградените цени','Prices are for parcels you hand in at a courier office. Changes take effect after you save.'=>'Цените са за пратки, предадени в офис на куриера. Промените влизат в сила след запазване.','Choose image'=>'Избор на изображение','Standardised audit file (Annex 38)'=>'Стандартизиран одиторски файл (Приложение 38)','The monthly XML file for the NRA under Ordinance N-18. There is no limit on the number of orders.'=>'Месечният XML файл за НАП по Наредба Н-18. Няма ограничение за броя поръчки.','Create XML file'=>'Създаване на XML файл','Invoice archive'=>'Архив с фактури','A ZIP file with all invoices and credit notes of the month.'=>'ZIP файл с всички фактури и кредитни известия за месеца.','Download archive'=>'Изтегляне на архива','Microinvest Delta'=>'Microinvest Delta','The documents of the month in the import format of Microinvest Delta.'=>'Документите за месеца във формата за импорт на Microinvest Delta.','Create file'=>'Създаване на файл','Ready-made files'=>'Готови файлове','Month'=>'Месец','Older orders'=>'По-стари поръчки','Create missing documents for orders placed before the plugin was installed'=>'Създаване на липсващите документи за поръчки отпреди инсталирането на разширението','Demo works with the courier\'s test system and nothing is really shipped. Switch to Live with your real login before you start sending.'=>'Демо работи с тестовата система на куриера и нищо не се изпраща наистина. Преминете на „Реална среда“ с истинските си данни за вход, преди да започнете да изпращате.','Turns the courier on: its shipping methods for your zones, its page in Couriers and the waybill box on each order.'=>'Включва куриера: методите му за доставка за зоните Ви, страницата му в „Куриери“ и полето за товарителница във всяка поръчка.','Turns on invoices, credit notes, the PDF look and the NRA audit file. The order document is made for every order either way.'=>'Включва фактурите, кредитните известия, вида на PDF и одиторския файл за НАП. Документът за продажба се създава за всяка поръчка и без това.','The courier prints it on the waybill, so whoever packs or delivers the parcel knows which order it is.'=>'Куриерът го отпечатва в товарителницата, така че който опакова или доставя пратката, знае коя е поръчката.','The status an order gets when the courier reports the parcel delivered.'=>'Статусът, който поръчката получава, когато куриерът отчете пратката като доставена.','Usually Completed. "Do not change" only adds a note to the order.'=>'Обикновено „Приключена“. „Без промяна“ само добавя бележка към поръчката.','For example Cancelled or On hold. The note on the order says what the courier reported.'=>'Например „Отказана“ или „Задържана“. Бележката към поръчката казва какво е отчел куриерът.','The username of your Econt account.'=>'Потребителското име на профила Ви в Еконт.','For a test, choose Demo and use the demo login shown under Environment.'=>'За тест изберете „Демо“ и използвайте демо данните, показани под „Среда“.','The password of your Econt account.'=>'Паролата на профила Ви в Еконт.','Stored on your site and sent only to Econt.'=>'Пази се на сайта Ви и се изпраща само на Еконт.','The Speedy username for online shops. It is not your MySpeedy login.'=>'Потребителското име на Спиди за онлайн магазини. Не е входът Ви за MySpeedy.','Speedy gives it with your contract. Without a contract, write to telesales@speedy.bg.'=>'Спиди го предоставя с договора. Без договор пишете на telesales@speedy.bg.','The password that goes with the Speedy username.'=>'Паролата към потребителското име на Спиди.','Stored on your site and sent only to Speedy.'=>'Пази се на сайта Ви и се изпраща само на Спиди.','From the email BOX NOW sends with your contract.'=>'От имейла, който BOX NOW изпраща с договора Ви.','Demo and live have different keys. Choose the environment that matches them.'=>'Демо и реалната среда имат различни ключове. Изберете средата, която им съответства.','Given by Pigeon Express for your account.'=>'Предоставя се от Pigeon Express за профила Ви.','Without them customers still choose Pigeon offices and lockers from Pigeon\'s public list, but waybills need them.'=>'Без тях клиентите пак избират офиси и автомати на Pigeon от публичния им списък, но товарителниците изискват тези данни.','Given by CVC for your account.'=>'Предоставя се от CVC за профила Ви.','Without it, CVC offices are not offered at checkout and waybills cannot be made.'=>'Без него офисите на CVC не се предлагат при плащане и не могат да се създават товарителници.','When the courier cannot price an order (no login, or no answer), the price comes from the list below. Off: the option shows no price then.'=>'Когато куриерът не може да изчисли цена (няма вход или не отговаря), цената се взема от листата по-долу. Изключено: тогава опцията не показва цена.','The courier\'s published prices by weight for each delivery type.'=>'Публикуваните цени на куриера по тегло за всеки вид доставка.','Edit them, or press "Check the courier website" to compare with the latest published prices.'=>'Редактирайте ги или натиснете „Проверка в сайта на куриера“, за да ги сравните с последно публикуваните цени.','An account can have several sender profiles. Waybills are made with the one you choose.'=>'Един профил може да има няколко профила на подател. Товарителниците се създават с избрания.','Sender contact on the waybill.'=>'Лице за контакт на подателя в товарителницата.','The courier contacts this person about pickups and problems with a parcel.'=>'Куриерът се свързва с това лице за вземане на пратки и проблеми с пратка.','Sender phone on the waybill.'=>'Телефон на подателя в товарителницата.','The courier calls this number about pickups and problems with a parcel.'=>'Куриерът звъни на този номер за вземане на пратки и проблеми с пратка.','Sender email on the waybill.'=>'Имейл на подателя в товарителницата.','The courier writes to this address about your parcels.'=>'Куриерът пише на този адрес за пратките Ви.','Use it only when the waybill contents miss sizes or colours of the products.'=>'Използвайте го само когато в съдържанието на товарителницата липсват размерите или цветовете на продуктите.','The waybill is made as soon as the order is placed and its number goes into the order emails. Leave it off if you check orders before shipping.'=>'Товарителницата се създава веднага щом поръчката е направена и номерът ѝ влиза в имейлите за поръчката. Оставете го изключено, ако проверявате поръчките преди изпращане.','Insures the parcel for the order value. The courier charges a little extra for it.'=>'Застрахова пратката за стойността на поръчката. Куриерът взема малка допълнителна такса за това.','Uses the product dimensions to fit the order into the courier\'s box sizes. Products without dimensions count as the default size.'=>'Използва размерите на продуктите, за да събере поръчката в кутиите на куриера. Продуктите без размери се броят с размера по подразбиране.','Your cash on delivery agreement with Econt: how and when Econt pays the collected money to you.'=>'Споразумението Ви за наложен платеж с Еконт: как и кога Еконт Ви изплаща събраните пари.','How you pay Econt for the shipments you send.'=>'Как плащате на Еконт за пратките, които изпращате.','Econt shows the customer either your invoice number or a packing list of the products.'=>'Еконт показва на клиента или номера на фактурата Ви, или опис на продуктите.','Address: the courier comes to you. Office: you take the parcels to a courier office, which is often cheaper. Save to see the next fields.'=>'Адрес: куриерът идва при Вас. Офис: Вие занасяте пратките в офис на куриера, което често е по-евтино. Запазете, за да видите следващите полета.','Where your parcels start. Prices are calculated from here.'=>'Откъдето тръгват пратките Ви. Цените се изчисляват оттук.','Speedy pays the collected money back by postal money transfer. Needs that agreement with Speedy and cannot be combined with ordinary cash on delivery.'=>'Спиди изплаща събраните пари с пощенски паричен превод. Изисква такова споразумение със Спиди и не може да се комбинира с обикновен наложен платеж.','Speedy issues the cash receipt for the collected amount on your behalf. Needs that agreement with Speedy.'=>'Спиди издава касовия бон за събраната сума от Ваше име. Изисква такова споразумение със Спиди.','Adds the administrative fee from your Speedy contract to the price, when the customer pays for delivery.'=>'Добавя административната такса от договора Ви със Спиди към цената, когато клиентът плаща доставката.','CVC pays the collected money back by postal money transfer. Needs that agreement with CVC.'=>'CVC изплаща събраните пари с пощенски паричен превод. Изисква такова споразумение с CVC.','Turn on if your CVC contract says you pay for the shipments.'=>'Включете, ако според договора Ви с CVC Вие плащате пратките.','The warehouse or locker BOX NOW collects your parcels from.'=>'Складът или автоматът, от който BOX NOW взема пратките Ви.','The customer can return the parcel at a BOX NOW locker.'=>'Клиентът може да върне пратката в автомат на BOX NOW.','BOX NOW has no price calculation in its API, so you set the prices here. Save after choosing to see the right table.'=>'BOX NOW няма изчисляване на цени в API-то си, затова задавате цените тук. Запазете след избора, за да видите правилната таблица.','Each row is a range and the price the customer pays in it.'=>'Всеки ред е диапазон и цената, която клиентът плаща в него.','For example 200: BOX NOW is not offered for bigger orders.'=>'Например 200: BOX NOW не се предлага за по-големи поръчки.','Orders above this total ship for free with BOX NOW.'=>'Поръчките над тази сума се доставят безплатно с BOX NOW.','The locker compartment size for orders whose products have no dimensions.'=>'Размерът на клетката в автомата за поръчки, чиито продукти нямат размери.','An extra Pigeon Express service. It may cost extra and must be in your contract.'=>'Допълнителна услуга на Pigeon Express. Може да струва допълнително и трябва да е в договора Ви.','Bulgaria only also hides the country field. "WooCommerce settings" keeps the countries of WooCommerce > Settings > General.'=>'„Само България“ скрива и полето за държава. „Настройки на WooCommerce“ запазва държавите от WooCommerce > Настройки > Общи.','Couriers search addresses in Cyrillic. Addresses typed in Latin letters are converted, so the parcel still finds the customer.'=>'Куриерите търсят адресите на кирилица. Адресите, написани на латиница, се преобразуват, така че пратката пак намира клиента.','Names on the waybill then match the customer\'s ID card.'=>'Тогава имената в товарителницата съвпадат с личната карта на клиента.','For themes with a narrow order summary: the shipping options take the full width.'=>'За теми с тясна обобщена част на поръчката: опциите за доставка заемат цялата ширина.','The company details go on the invoice and into the NRA audit file.'=>'Данните на фирмата влизат във фактурата и в одиторския файл за НАП.','Hidden: customers cannot leave a note with the order.'=>'Скрито: клиентите не могат да оставят бележка към поръчката.','Order, visibility and width of every checkout field, and your own fields.'=>'Ред, видимост и ширина на всяко поле при плащане, както и Ваши полета.','The notes above the table say which checkouts follow which part.'=>'Бележките над таблицата казват кои видове плащане следват коя част.','Cards with a border, or the plain list of your theme.'=>'Карти с рамка или обикновеният списък на темата Ви.','Cards make the chosen courier stand out.'=>'Картите открояват избрания куриер.','Shows "To an office", "To a parcel locker" or "To an address" under each option.'=>'Показва „До офис“, „До автомат за пратки“ или „До адрес“ под всяка опция.','Empty: the colour of your design tokens or theme.'=>'Празно: цветът от дизайн токените или темата Ви.','Any CSS colour, for example #1a7f37 or var(--primary).'=>'Всеки CSS цвят, например #1a7f37 или var(--primary).','Empty: the size of your design tokens or theme.'=>'Празно: размерът от дизайн токените или темата Ви.','Any CSS size, for example 8px, 0.5rem or var(--space-s).'=>'Всеки CSS размер, например 8px, 0.5rem или var(--space-s).','Required by EU law from 19 June 2026 for shops with online checkout.'=>'Задължително по правото на ЕС от 19 юни 2026 г. за магазини с онлайн плащане.','Or place the link yourself with the shortcode [nashenski_withdrawal_link].'=>'Или поставете връзката сами с краткия код [nashenski_withdrawal_link].','14 days is the legal minimum; give more if your terms promise more.'=>'14 дни е законовият минимум; дайте повече, ако общите Ви условия обещават повече.','As in the Commercial Register.'=>'Както в Търговския регистър.','The person who represents the company.'=>'Лицето, което представлява фирмата.','9 or 13 digits. The NRA audit file cannot be made without it.'=>'9 или 13 цифри. Одиторският файл за НАП не може да се създаде без него.','For a company that is not registered for VAT: invoices carry the note about Article 113(9) and show no VAT. Works while WooCommerce taxes are off.'=>'За фирма без регистрация по ДДС: фактурите съдържат текста за чл. 113, ал. 9 и не показват ДДС. Работи, докато данъците в WooCommerce са изключени.','Starts with BG. Leave empty if you are not registered for VAT.'=>'Започва с BG. Оставете празно, ако нямате регистрация по ДДС.','Customers who ask for a company invoice must then enter the company VAT number.'=>'Клиентите, които искат фактура на фирма, трябва тогава да въведат ДДС номера на фирмата.','Shown on your documents.'=>'Показва се в документите Ви.','Town of the registered address.'=>'Населеното място на адреса на регистрация.','Registered address, shown on invoices.'=>'Адрес на регистрация, показва се във фактурите.','Customers and the NRA may write to this address about documents.'=>'Клиентите и НАП могат да пишат на този адрес за документите.','The NRA gives it when you register the online shop.'=>'НАП го дава при регистрацията на онлайн магазина.','The shop address as registered with the NRA.'=>'Адресът на магазина, както е регистриран в НАП.','Needed by shops that take card or bank payments without a fiscal receipt (Ordinance N-18, Article 52o).'=>'Нужно е за магазини, които приемат плащания с карта или по банка без касов бон (Наредба Н-18, чл. 52о).','Which orders get an invoice automatically.'=>'Кои поръчки получават фактура автоматично.','"Only for companies" makes invoices for customers who ticked "I want an invoice for a company". Any order can also get one by hand.'=>'„Само за фирми“ създава фактури за клиентите, които са отметнали „Искам фактура на фирма“. Всяка поръчка може да получи фактура и на ръка.','When the order document and invoice are made.'=>'Кога се създават документът за продажба и фактурата.','"Order completed" waits until you complete the order, so cancelled orders get no documents.'=>'„При изпълнение на поръчката“ изчаква, докато завършите поръчката, така че отказаните поръчки не получават документи.','Use it when the courier issues its own receipt for the delivery charge.'=>'Използвайте го, когато куриерът издава собствен документ за цената на доставката.','The number of the next order document, 10 digits.'=>'Номерът на следващия документ за продажба, 10 цифри.','Leave empty to number invoices together with order documents.'=>'Оставете празно, за да се номерират фактурите заедно с документите за продажба.','Days from the invoice date to the payment due date.'=>'Дни от датата на фактурата до падежа на плащането.','Printed as the person who prepared the document.'=>'Отпечатва се като лицето, съставило документа.','Bulgarian invoices may carry an identification code instead of a signature.'=>'Българските фактури може да съдържат идентификационен код вместо подпис.','Printed at the bottom of every document.'=>'Отпечатва се в долната част на всеки документ.','For example your bank account or a thank-you line.'=>'Например банковата Ви сметка или ред с благодарност.','Bulgarian invoices often show the total in words.'=>'Българските фактури често показват сумата словом.','Turn on to send the copies to your accountant.'=>'Включете, за да се изпращат копията на счетоводителя Ви.','Your accountant\'s email address.'=>'Имейл адресът на счетоводителя Ви.','The file is due by the 15th of the next month. Your accountant gets it on the 1st.'=>'Файлът се подава до 15-о число на следващия месец. Счетоводителят Ви го получава на 1-во.','Products in these tax classes count as digital goods for EU VAT: the customer\'s country rate applies.'=>'Продуктите в тези данъчни класове се смятат за цифрови стоки за ДДС в ЕС: прилага се ставката на държавата на клиента.','The VAT group of your sales in the NRA audit file. Most shops sell in group B (20%).'=>'ДДС групата на продажбите Ви в одиторския файл за НАП. Повечето магазини продават в група Б (20%).','How you pay customers back for cancelled orders.'=>'Как връщате парите на клиентите при отказани поръчки.','Goes into the NRA audit file for refunded orders.'=>'Влиза в одиторския файл за НАП при върнати поръчки.','Yes: for cash on delivery orders with this method, the delivery charge is left out of the order document and the NRA file, because the courier collects it and gives its own receipt.'=>'Да: при поръчки с наложен платеж с този метод цената на доставката не влиза в документа за продажба и в одиторския файл, защото куриерът я събира и издава собствен документ.','The NRA payment type of this payment method.'=>'Видът плащане за НАП за този метод на плащане.','How the NRA audit file reports payments made with this method.'=>'Как одиторският файл за НАП отчита плащанията с този метод.','The number of the virtual POS terminal from your bank.'=>'Номерът на виртуалния ПОС терминал от банката Ви.','Needed in the NRA audit file for card payments.'=>'Нужен е в одиторския файл за НАП при плащания с карта.','The identifier of the payment provider, if it gave you one.'=>'Идентификаторът на доставчика на плащания, ако Ви е дал такъв.','Goes into the NRA audit file with each payment.'=>'Влиза в одиторския файл за НАП с всяко плащане.','A PNG or JPG about 600 pixels wide prints sharp.'=>'PNG или JPG с ширина около 600 пиксела се отпечатва ясно.','How big the logo is at the top of the document.'=>'Колко голямо е логото в горната част на документа.','Larger logos push the document down; Small keeps long orders on one page.'=>'По-голямото лого избутва документа надолу; „Малко“ запазва дългите поръчки на една страница.','Turn off when your logo already has these details.'=>'Изключете, когато логото Ви вече съдържа тези данни.','Documents then keep the colours of your site.'=>'Тогава документите следват цветовете на сайта Ви.','Pick a colour or type a hex code.'=>'Изберете цвят или въведете шестнадесетичен код.','Dark text on a light table header prints best.'=>'Тъмен текст върху светла заглавна част на таблицата се отпечатва най-добре.','Both have Cyrillic letters.'=>'И двата имат кирилица.','Size of the document text.'=>'Размер на текста в документа.','Smaller text fits more products on a page.'=>'По-малкият текст побира повече продукти на страница.','The page size of the PDF documents.'=>'Размерът на страницата на PDF документите.','A4 suits most office printers.'=>'A4 е подходящ за повечето офис принтери.','Compact fits long orders on one page.'=>'„Сбито“ побира дългите поръчки на една страница.','How dates look on the documents.'=>'Как изглеждат датите в документите.','Bulgarian documents usually use day.month.year.'=>'Българските документи обикновено използват ден.месец.година.','Turn off to keep phone numbers and emails off printed documents.'=>'Изключете, за да няма телефони и имейли в отпечатаните документи.','The space where the customer signs on receipt.'=>'Мястото, където клиентът се подписва при получаване.','Asks this service about the customer\'s phone number when you open an order. Needs the service\'s key below.'=>'Пита тази услуга за телефона на клиента, когато отворите поръчка. Изисква ключа на услугата по-долу.','A warning sign in the orders list for customers with reports.'=>'Предупредителен знак в списъка с поръчки за клиенти със сигнали.','Customers with refused parcels then pay online or by bank transfer.'=>'Клиентите с отказани пратки тогава плащат онлайн или по банков път.','From your account on the service\'s website.'=>'От профила Ви в сайта на услугата.','Lower means stricter: more customers get a warning.'=>'По-ниско значи по-строго: повече клиенти получават предупреждение.','Shares your waybills with NepoStop, so its data about refused parcels grows. Tell your customers in your privacy policy.'=>'Споделя товарителниците Ви с NepoStop, така че данните му за отказани пратки растат. Уведомете клиентите си в политиката за поверителност.','The name customers see at checkout.'=>'Името, което клиентите виждат при плащане.','Short is best, for example "To an office". The courier logo is shown next to it.'=>'Най-добре е кратко, например „До офис“. Логото на куриера се показва до него.','Add one method per delivery type to the zone.'=>'Добавете към зоната по един метод за всеки вид доставка.','Office and parcel locker show a list and a map; address shows the street search.'=>'Офис и автомат показват списък и карта; адрес показва търсене на улица.','Whether the customer may open or test the parcel before paying.'=>'Дали клиентът може да отвори или тества пратката преди плащане.','Not possible at parcel lockers. If the customer refuses after a test, the return is paid as your contract says.'=>'Не е възможно при автомати. Ако клиентът откаже след тест, връщането се плаща според договора Ви.','The courier texts the customer about the delivery. It may cost extra.'=>'Куриерът изпраща SMS на клиента за доставката. Може да струва допълнително.','Delivery and pickup on Saturdays. It may cost extra.'=>'Доставка и вземане в събота. Може да струва допълнително.','Orders above this total ship for free with this method.'=>'Поръчките над тази сума се доставят безплатно с този метод.','You still pay the courier; the customer sees "Free".'=>'Вие пак плащате на куриера; клиентът вижда „Безплатно“.','A set delivery price instead of the courier\'s calculation.'=>'Определена цена за доставка вместо изчислението на куриера.','The difference to the real courier price is yours.'=>'Разликата до реалната цена на куриера е за Ваша сметка.','Speedy Delivery'=>'Доставка със Спиди','Fill in at least one of street number, block, entrance, floor or apartment.'=>'Попълнете поне едно от: номер на улица, блок, вход, етаж или апартамент.','Physical Weight'=>'Физическо тегло','Volumetric weight'=>'Обемно тегло','Chargeable weight'=>'Тегло за таксуване','You just copied the label data used for the Speedy API.'=>'Копирахте данните за товарителницата, изпратени към API на Спиди.','A4 with copy on same page'=>'A4 с копие на същата страница','A4 with copy on single page'=>'A4 с копие на отделна страница','BOX NOW'=>'BOX NOW','Demo'=>'Демо','Live'=>'Реална среда','Environment'=>'Среда','Select used environment.'=>'Изберете средата.','Client ID'=>'Client ID','Enter your Client ID.'=>'Въведете вашия Client ID.','Client Secret'=>'Client Secret','Enter your Client Secret.'=>'Въведете вашия Client Secret.','Phone'=>'Телефон','E-mail'=>'Имейл','Location'=>'Местоположение','Generate label after checkout'=>'Създаване на товарителница след поръчка','This option will try to generate your label immediately after user checkout. Also, will add the tracking number in the order email.'=>'Опитва да създаде товарителницата веднага след поръчката на клиента и добавя номера за проследяване в имейла за поръчката.','From/To in kg'=>'От/до в кг','From/To Order Total'=>'От/до сума на поръчката','From/To kg and Order Total'=>'От/до кг и сума на поръчката','Price type'=>'Вид цена','After you select the option, you must save the settings in order the correct price settings to be shown.'=>'След като изберете опцията, запазете настройките, за да се покажат правилните полета за цена.','kg'=>'кг',' to '=>' до ','+ Add new row'=>'+ Добавяне на ред','and'=>'и','Hide shipping over cart total price'=>'Скриване на доставката над сума на количката','If filled will hide the shipping method if the cart total price is over the sum.'=>'Ако е попълнено, методът за доставка се скрива, когато сумата в количката е над тази стойност.','Free shipping over'=>'Безплатна доставка над','Free shipping over total cart price.'=>'Безплатна доставка над тази сума на количката.','Default box size'=>'Размер на кутията по подразбиране','BOX NOW account'=>'Профил в BOX NOW','Client ID and secret from your BOX NOW e-shop account. After saving, the sender and price options appear.'=>'Client ID и Client Secret от вашия профил за онлайн магазин в BOX NOW. След запазване се появяват настройките за подател и цени.','Where you hand over parcels'=>'Къде предавате пратките','What customers pay'=>'Какво плащат клиентите','How Nashenski Commerce calculates the BOX NOW price at checkout.'=>'Как Нашенски Комерс изчислява цената на BOX NOW при плащане.','Incorrect Client ID or Client Secret.'=>'Грешен Client ID или Client Secret.','Connectix'=>'Connectix','Sandbox'=>'Тестова среда','Token'=>'Токен','Enter the provided token from connectix.bg.'=>'Въведете токена, получен от connectix.bg.','Low'=>'Ниско','Medium'=>'Средно','High'=>'Високо','Ultra high'=>'Много високо','Level of Warning'=>'Ниво на предупреждение','Choose level of warning that will trigger notification or disable COD.'=>'Изберете нивото, от което да има предупреждение или да се скрие наложеният платеж.','Send tracking information'=>'Изпращане на данни за проследяване','By enabling this option, the plugin will send Speedy and Econt tracking numbers to Connectix.bg. This way, you will help the service work better.'=>'Разширението изпраща номерата за проследяване на Спиди и Еконт към Connectix.bg. Така помагате услугата да работи по-добре.','Token is incorrect.'=>'Токенът е грешен.','CVC'=>'CVC','API Token'=>'API токен','Enter your token.'=>'Въведете токена.','Enter sender name.'=>'Въведете име на подателя.','Enter sender phone.'=>'Въведете телефон на подателя.','Enter sender email.'=>'Въведете имейл на подателя.','Cash on delivery as PPP.'=>'Наложен платеж като ППП.','Pay by contract'=>'Плащане по договор','Force variations in label'=>'Вариациите в товарителницата','Add additional variations information. Please use this option only if you want the variation data to be available in the label print and it\'s missing.'=>'Добавя данни за вариациите. Използвайте само ако данните за вариацията липсват при печат на товарителницата.','City'=>'Град','Select from where you will send the packages and save to show more options.'=>'Изберете откъде ще изпращате пратките и запазете, за да видите още настройки.','Select Address'=>'Изберете адрес','CVC account'=>'Профил в CVC','The API token CVC gave you. After saving, your sender options appear.'=>'API токенът, който CVC ви е дал. След запазване се появяват настройките за подател.','Where you send from'=>'Откъде изпращате','API Token is incorrect.'=>'API токенът е грешен.','Econt'=>'Еконт','Select used environment. For demo you can use Username: "iasp-dev" and Password: "1Asp-dev". For live environment use your credentials or create a registration at <a target="_blank" href="https://login.econt.com/register/">Econt Delivery</a>'=>'Изберете средата. За демо използвайте потребител „iasp-dev“ и парола „1Asp-dev“. За реалната среда използвайте вашите данни или се регистрирайте в <a target="_blank" href="https://login.econt.com/register/">Econt Delivery</a>','Username'=>'Потребител','Enter your username.'=>'Въведете потребителското си име.','Password'=>'Парола','Enter your password.'=>'Въведете паролата си.','Select profile'=>'Изберете профил','Select the profile you want to use and save to show or update the other options.'=>'Изберете профила, който искате да използвате, и запазете, за да видите или обновите другите настройки.','Adds declared value to the label if payment is COD.'=>'Добавя обявена стойност към товарителницата при наложен платеж.','Automatically calculate box size'=>'Автоматично изчисляване на размера на кутията','Automatically calculate LxWxH of the box for the parcel.'=>'Автоматично изчислява дължината, ширината и височината на кутията за пратката.','Cash on delivery agreement'=>'Споразумение за наложен платеж','Choose cash on delivery agreement'=>'Изберете споразумение за наложен платеж','Credit'=>'Кредит','Cash'=>'В брой','Sender payment type'=>'Начин на плащане от подателя','Select how you will pay for the shipments.'=>'Изберете как ще плащате за пратките.','Packing list'=>'Опис','Packing list or invoice number'=>'Опис или номер на фактура','Select if you want to have packing list or invoice number in the label.'=>'Изберете дали в товарителницата да има опис или номер на фактура.','Choose a city and save in order to show offices.'=>'Изберете град и запазете, за да се покажат офисите.','No agreement'=>'Без споразумение','Econt account'=>'Профил в Еконт','Use the user and password of an Econt e-shop integration. After saving, your profiles and label options appear.'=>'Използвайте потребителя и паролата от интеграцията за онлайн магазин в Еконт. След запазване се появяват профилите ви и настройките за товарителници.','Username and password are incorrect. Create API keys in your Econt account under "Integration for online shops".'=>'Потребителското име и паролата са грешни. Създайте API ключове в профила си в Еконт, в „Интеграция за онлайн магазини“.','No profiles was found. Please contact with Econt.'=>'Не са открити профили. Свържете се с Еконт.','Export'=>'Експорт','Fill in the company EIK (9 or 13 digits) in %s and save, then create the file again.'=>'Попълнете ЕИК на фирмата (9 или 13 цифри) в %s и запазете, после създайте файла отново.','No orders found for this month.'=>'Няма поръчки за този месец.','Some of the orders was not included because the payment method options was not found or the payment method was disabled. List of orders id\'s: %s'=>'Някои поръчки не са включени, защото настройките за начина им на плащане липсват или начинът на плащане е изключен. Номера на поръчките: %s','Found errors in file:'=>'Открити грешки във файла:','File generated successfully! <a href="%s" download target="_blank">Download</a>'=>'Файлът е създаден! <a href="%s" download target="_blank">Изтегляне</a>','Checkout fields'=>'Полета при плащане','Company invoice fields'=>'Полета за фактура на фирма','Add "I want an invoice for a company" to the checkout. When ticked, the customer fills in company name, EIK, VAT number, MOL, town and address, and the invoice is made out to the company.'=>'Добавя „Искам фактура на фирма“ към плащането. Когато е отметнато, клиентът попълва име на фирмата, ЕИК, ДДС номер, МОЛ, населено място и адрес, и фактурата се издава на фирмата.','Default (as WooCommerce shows it)'=>'По подразбиране (както го показва WooCommerce)','Order notes'=>'Бележки към поръчката','Classic checkout only. In the block checkout, turn order notes on or off in the Checkout block settings.'=>'Само при класическото плащане. При блоковото плащане включете или изключете бележките в настройките на блока за плащане.','Company invoice'=>'Фактура на фирма','Works in the classic checkout, the block checkout and page builder checkouts. In a builder checkout made of single field elements, the fields appear after the billing fields unless you placed them yourself.'=>'Работи при класическото плащане, при блоковото плащане и при плащане, създадено с конструктор. В плащане от отделни полета, създадено с конструктор, полетата се показват след полетата за фактуриране, освен ако не сте ги поставили сами.','nekorekten.com'=>'nekorekten.com','API key'=>'API ключ','Create a key in your %s profile under "API keys" and allow your server\'s IP address.'=>'Създайте ключ в профила си в %s, в „API ключове“, и разрешете IP адреса на сървъра си.','Reports for a warning'=>'Сигнали за предупреждение','Number of reports'=>'Брой сигнали','From how many reports about a phone number the order shows a warning and cash on delivery is turned off at checkout.'=>'От колко сигнала за един телефонен номер поръчката показва предупреждение и наложеният платеж се изключва при плащане.','Enter your nekorekten.com API key.'=>'Въведете API ключа си за nekorekten.com.','nekorekten.com did not accept the API key. Check the key and the allowed IP addresses in your nekorekten.com profile.'=>'nekorekten.com не прие API ключа. Проверете ключа и разрешените IP адреси в профила си в nekorekten.com.','NepoStop'=>'NepoStop','API Key'=>'API ключ','Enter the provided API key from nepostop.com.'=>'Въведете API ключа, получен от nepostop.com.','In percentages'=>'В проценти','Enter how many percentages will trigger a warning or disable COD.'=>'Въведете от колко процента да има предупреждение или да се скрие наложеният платеж.','Automatically upload labels to nepostop.com'=>'Автоматично качване на товарителниците в nepostop.com','By enabling this option, the plugin will send Speedy and Econt tracking numbers to nepostop.com and you can track them from their platform. This way, you will help the service work better.'=>'Разширението изпраща номерата за проследяване на Спиди и Еконт към nepostop.com и можете да ги следите в тяхната платформа. Така помагате услугата да работи по-добре.','API Key is incorrect.'=>'API ключът е грешен.','Company Name'=>'Име на фирмата','Your company name.'=>'Името на вашата фирма.','MOL'=>'МОЛ','Your company MOL.'=>'МОЛ на вашата фирма.','EIK'=>'ЕИК','Your company EIK.'=>'ЕИК на вашата фирма.','Company registered under Article 113(9) of the Bulgarian VAT Act'=>'Фирмата е регистрирана по чл. 113, ал. 9 от ЗДДС','VAT Number'=>'ДДС номер','Your company VAT Number. To be filled in if you have a VAT registration.'=>'ДДС номерът на вашата фирма. Попълва се, ако имате регистрация по ДДС.','VAT number required on checkout?'=>'Задължителен ДДС номер при плащане?','Company phone Number'=>'Телефон на фирмата','Contact phone number of your company.'=>'Телефон за връзка с вашата фирма.','Settlement'=>'Населено място','The place of registration of your company.'=>'Мястото на регистрация на вашата фирма.','Company Address'=>'Адрес на фирмата','The registration address of your company.'=>'Адресът на регистрация на вашата фирма.','Contact email'=>'Имейл за връзка','NRA unique number'=>'Уникален номер от НАП','The number received by the NRA when submitting information under Art. 52p according to Annex № 33.'=>'Номерът, получен от НАП при подаване на данни по чл. 52р съгласно Приложение № 33.','Domain Name'=>'Име на домейна','Web address of the e-shop. It is introduced in the same way as when submitting information under Art. 52p according to Annex № 33 in the portal for electronic services of the NRA.'=>'Уеб адресът на онлайн магазина. Въвежда се така, както при подаване на данни по чл. 52р съгласно Приложение № 33 в портала за електронни услуги на НАП.','Enable N-18'=>'Включване на Н-18','Turn on the NRA audit file (XML) in Exports. The order document is made for every order either way.'=>'Включва одиторския файл за НАП (XML) в Експорти. Документът за поръчка се създава за всяка поръчка и без тази настройка.','Disable invoice generation'=>'Без издаване на фактури','Add only fields on checkout'=>'Само полетата при плащане','Only for companies'=>'Само за фирми','Always'=>'Винаги','When to generate invoices?'=>'Кога да се издават фактури?','Order created'=>'При създаване на поръчката','Order completed'=>'При изпълнение на поръчката','When to generate documents?'=>'Кога да се създават документите?','Remove delivery from documents'=>'Без доставката в документите','This option will remove the delivery from invoices and XML file.'=>'Премахва доставката от фактурите и от XML файла.','Next NRA Document Number'=>'Следващ номер на документ за НАП','The document number of the next order.'=>'Номерът на документа за следващата поръчка.','Next Invoice/Credit notice Number'=>'Следващ номер на фактура/кредитно известие','If it\' filled the invoices will have different number than the NRA documents.'=>'Ако е попълнено, фактурите ще имат различна номерация от документите за НАП.','Due days'=>'Дни до падеж','Days added to documents due date.'=>'Дни, добавени към датата за плащане в документите.','Prepared by'=>'Съставил','Enter the name of the compiler of the automatically generated documents, which will be displayed in them.'=>'Въведете името на съставителя на автоматично създаваните документи, което да се показва в тях.','Identification code'=>'Идентификационен код','Enter an ID in the invoices and credit memos that replace the compiler\'s signature.'=>'Въведете код във фактурите и кредитните известия, който замества подписа на съставителя.','Footer text'=>'Текст в долния колонтитул','Total in words'=>'Сума словом','Print the total in Bulgarian words under the table, in euro. Older orders in leva stay in leva.'=>'Отпечатва сумата словом под таблицата, в евро. По-старите поръчки в лева остават в лева.','Generate separate copy documents'=>'Отделни документи за копията','When enabled, invoice and credit notice copies will be generated as separate documents instead of being merged with the original. The copies can be sent to an accountant email.'=>'Копията на фактурите и кредитните известия се създават като отделни документи, вместо да се обединяват с оригинала. Копията могат да се изпращат на имейла на счетоводителя.','Accountant email'=>'Имейл на счетоводителя','Separate several addresses with commas. Gets the invoice and credit notice copies when separate copy documents are on, and the monthly audit file when that is on.'=>'Разделете няколко адреса със запетая. Получава копията на фактурите и кредитните известия, когато отделните копия са включени, и месечния одиторски файл, когато той е включен.','Email the audit file every month'=>'Одиторски файл по имейл всеки месец','On the 1st of each month, the NRA audit file (XML, Ordinance N-18) of the month before goes to the accountant email.'=>'На 1-во число всеки месец одиторският файл за НАП (XML, Наредба Н-18) за предходния месец се изпраща на имейла на счетоводителя.','Group - A'=>'Група А','Group - B'=>'Група Б','Group - G'=>'Група Г','Vat Group'=>'Данъчна група','group "A" - for goods and services, the sales of which are exempt from taxation, for goods and services, the sales of which are subject to 0% VAT, as well as for sales, for which VAT is not charged; group "B" - for goods and services, the sales of which are subject to 20% value added tax; group "D" - for goods and services, the sales of which are subject to 9% value added tax; combined - the group is determined for each product in the store separately.'=>'група „А“ - за стоки и услуги, чиито продажби са освободени от облагане, за стоки и услуги, чиито продажби се облагат с 0% ДДС, както и за продажби, за които не се начислява ДДС; група „Б“ - за стоки и услуги, чиито продажби се облагат с 20% данък върху добавената стойност; група „Г“ - за стоки и услуги, чиито продажби се облагат с 9% данък върху добавената стойност; комбинирана - групата се определя за всеки продукт в магазина поотделно.','Return method'=>'Начин на връщане','How to return the amount when the client cancel the order.'=>'Как се връща сумата, когато клиентът откаже поръчката.','Logo'=>'Лого','Shown at the top of every document. Without one, the site logo from the theme or the site icon is used.'=>'Показва се най-горе във всеки документ. Ако няма, се използва логото на сайта от темата или иконата на сайта.','Small'=>'Малко','Large'=>'Голямо','Logo size'=>'Размер на логото','Website details'=>'Данни за сайта','Show the website name, address, email and phone under the logo'=>'Показване на името, адреса, имейла и телефона на сайта под логото','Follow TokenForge colours'=>'Цветове от TokenForge','Use the TokenForge palette for the colours below, now and after you change it'=>'Използване на палитрата на TokenForge за цветовете по-долу, сега и след като я промените','Title colour'=>'Цвят на заглавието','Document title and website name.'=>'Заглавието на документа и името на сайта.','Accent colour'=>'Акцентен цвят','Lines under the header and above the footer.'=>'Линиите под горния и над долния колонтитул.','Text colour'=>'Цвят на текста','Table header background'=>'Фон на заглавния ред на таблицата','Sans serif (DejaVu Sans)'=>'Безсерифен (DejaVu Sans)','Serif (DejaVu Serif)'=>'Серифен (DejaVu Serif)','Font'=>'Шрифт','Both fonts print Cyrillic and Latin.'=>'И двата шрифта поддържат кирилица и латиница.','Normal'=>'Нормален','Text size'=>'Размер на текста','A4'=>'A4','Letter'=>'Letter','Paper size'=>'Размер на хартията','Compact'=>'Сбито','Spacious'=>'Просторно','Spacing'=>'Разстояния','Line spacing of the supplier and customer boxes and padding of the tables.'=>'Разстояние между редовете в полетата на доставчика и получателя и отстъп в таблиците.','Date format'=>'Формат на датата','Phone and email'=>'Телефон и имейл','Show the phone and email of the supplier and the customer'=>'Показване на телефона и имейла на доставчика и получателя','Received by'=>'Получил','Show the "Received" box with the customer name'=>'Показване на полето „Получил“ с името на клиента','Payment method: %s'=>'Начин на плащане: %s','Company details'=>'Данни за фирмата','Printed on invoices and used in the NRA audit file.'=>'Отпечатват се във фактурите и се използват в одиторския файл за НАП.','VAT and refunds'=>'ДДС и възстановявания','Shipping on documents'=>'Доставка в документите','PDF appearance'=>'Вид на PDF документите','TokenForge is active: its colours fill in the fields below, and with "Follow TokenForge colours" on, documents keep matching the website.'=>'TokenForge е активен: цветовете му попълват полетата по-долу, а с „Цветове от TokenForge“ документите продължават да съвпадат със сайта.','Logo, colours, font and paper of invoices, credit notes and order documents.'=>'Лого, цветове, шрифт и хартия на фактурите, кредитните известия и документите за продажба.','Payment Type'=>'Вид плащане','Manner of payment of the order according to the NRA system.'=>'Начин на плащане на поръчката според системата на НАП.','Virtual POS №'=>'Виртуален ПОС №','Identifier'=>'Идентификатор','Is %s courier?'=>'%s куриер ли е?','If set to yes, all deliveries with PPP will be removed from documents and XML export'=>'Ако е „да“, всички доставки с ППП се премахват от документите и от XML експорта','Enter your API key.'=>'Въведете API ключа си.','API Secret'=>'API Secret','Enter your API secret.'=>'Въведете API Secret.','Pay with POS'=>'Плащане с ПОС','POS payment available.'=>'Възможно е плащане с ПОС.','Paper Return Receipt'=>'Хартиена обратна разписка','Request for a paper receipt'=>'Искане на хартиена разписка','Return Receipt'=>'Обратна разписка','Request for a return receipt in electronic format'=>'Искане на обратна разписка в електронен вид','Service Return Documents'=>'Връщане на документи','Return of original documents from the recipient to the sender after signing.'=>'Връщане на оригиналните документи от получателя към подателя след подписване.','ID Verification and Document Signature'=>'Проверка на самоличността и подписване на документи','Verify ID and sign documents electronically.'=>'Проверка на самоличността и електронно подписване на документи.','COD Card Fee'=>'Такса за плащане с карта при наложен платеж','Charge a fee for COD card payments.'=>'Таксуване на плащанията с карта при наложен платеж.','Enter your address.'=>'Въведете адреса си.','Pigeon Express account'=>'Профил в Pigeon Express','The API key and secret Pigeon Express gave you. After saving, your sender options appear.'=>'API ключът и API Secret, които Pigeon Express ви е дал. След запазване се появяват настройките за подател.','Extra services on labels'=>'Допълнителни услуги в товарителниците','You can see the current prices on the <a href="%s" target="_blank">Pigeon Express website</a> or according to your agreed upon terms.'=>'Текущите цени можете да видите на <a href="%s" target="_blank">сайта на Pigeon Express</a> или според договорените условия.','API Key and API Secret are incorrect.'=>'API ключът и API Secret са грешни.','Settings'=>'Настройки','Delivery to Econt offices, lockers and addresses'=>'Доставка до офиси, автомати и адреси на Еконт','Speedy'=>'Спиди','Delivery to Speedy offices, lockers and addresses'=>'Доставка до офиси, автомати и адреси на Спиди','Delivery to BOX NOW lockers'=>'Доставка до автомати на BOX NOW','Delivery to Pigeon Express offices, lockers and addresses'=>'Доставка до офиси, шкафчета и адреси на Pigeon Express','Delivery to CVC offices and addresses'=>'Доставка до офиси и адреси на CVC','Invoices and N-18'=>'Фактури и Н-18','Order documents, invoices, credit notes and the NRA audit file'=>'Документи за продажба, фактури, кредитни известия и одиторски файл за НАП','Reports about the customer\'s phone number from nekorekten.com'=>'Сигнали за телефонния номер на клиента от nekorekten.com','Delivery history of the customer from connectix.bg'=>'История на доставките на клиента от connectix.bg','Share of refused parcels for the customer\'s phone number from nepostop.com'=>'Дял на отказаните пратки за телефонния номер на клиента от nepostop.com','Orders list'=>'Списък с поръчки','Add a "Reports" column to the orders list'=>'Добавя колона „Сигнали“ в списъка с поръчки','Check the phone number at checkout and hide cash on delivery when reports are found'=>'Проверка на телефонния номер при плащане и скриване на наложения платеж при открити сигнали','nekorekten.com answers at most 10 checks a minute; Nashenski Commerce remembers answers for 10 minutes.'=>'nekorekten.com отговаря на най-много 10 проверки в минута; Нашенски Комерс помни отговорите 10 минути.','What Nashenski Commerce does in this store'=>'Какво прави Нашенски Комерс в този магазин','Turn on the couriers you work with and the documents you need. Each one adds its own settings: couriers in the Couriers section, documents in the Documents section.'=>'Включете куриерите, с които работите, и документите, които ви трябват. Всеки добавя свои настройки: куриерите в раздел Куриери, документите в раздел Документи.','Find out before shipping whether a customer tends to refuse parcels. Turn on a service, save, and enter its API key below.'=>'Разберете преди изпращане дали клиентът често отказва пратки. Включете услуга, запазете и въведете API ключа ѝ по-долу.','Shipping'=>'Доставка','Bulgaria only (country field hidden)'=>'Само България (полето за държава е скрито)','As set in WooCommerce > Settings > General'=>'Както е зададено в WooCommerce > Настройки > Общи','With Bulgaria only, every order is for Bulgaria and customers do not see the country field.'=>'При „Само България“ всяка поръчка е за България и клиентите не виждат полето за държава.','Courier logos'=>'Лога на куриерите','Show the courier logo next to each shipping option at checkout and in the cart.'=>'Показване на логото на куриера до всяка опция за доставка при плащане и в количката.','Converts the address the customer typed when the order is placed, for example "Ruse, ul. Tsar Osvoboditel" to "Русе, ул. Цар Освободител". Labels use the converted address. Orders also get a "Transliterate addresses" action.'=>'Преобразува адреса, който клиентът е въвел, при създаване на поръчката, например „Ruse, ul. Tsar Osvoboditel“ в „Русе, ул. Цар Освободител“. Товарителниците използват преобразувания адрес. Поръчките получават и действие „Транслитерация на адресите“.','Transliterate names too'=>'Транслитерация и на имената','Also convert first and last names.'=>'Преобразуват се и собствените и фамилните имена.','Alternative shipping options layout ( checkout )'=>'Алтернативно подреждане на опциите за доставка (плащане)','Make shipping options on 2 rows and full width in the checkout table.'=>'Опциите за доставка са на 2 реда и на цялата ширина на таблицата при плащане.','Countries and delivery options'=>'Държави и опции за доставка','Applies to every checkout: classic, block and page builder checkouts.'=>'Важи за всяко плащане: класическо, блоково и създадено с конструктор.','Cash on delivery with cash receipt.'=>'Наложен платеж с касова бележка.','Administrative fee on price calculations'=>'Административна такса при изчисляване на цените','Usage of administrative fee is enabled and configured in client contract. Ignored if not applicable for user.'=>'Административната такса е включена и настроена в договора с клиента. Пренебрегва се, ако не важи за потребителя.','If you choose "Address" the profile address will be used.'=>'Ако изберете „Адрес“, се използва адресът от профила.','Speedy account'=>'Профил в Спиди','The user and password of your Speedy API account. After saving, your client profiles and label options appear.'=>'Потребителят и паролата на вашия API профил в Спиди. След запазване се появяват клиентските профили и настройките за товарителници.','Username and password are incorrect.'=>'Потребителското име и паролата са грешни.','No profiles was found. Please contact with Speedy.'=>'Не са открити профили. Свържете се със Спиди.','No Info'=>'Няма информация','Speedy is not connected.'=>'Спиди не е свързан.','Sales for the accountant'=>'Продажби за счетоводителя','Shipments'=>'Пратки','Order ID'=>'ID на поръчката','Order number'=>'Номер на поръчката','Order date'=>'Дата на поръчката','Paid on'=>'Платена на','Completed on'=>'Изпълнена на','Currency'=>'Валута','Customer note'=>'Бележка от клиента','Created via'=>'Създадена чрез','Customer'=>'Клиент','Customer name'=>'Име на клиента','First name'=>'Име','Last name'=>'Фамилия','Email'=>'Имейл','Customer account ID'=>'ID на профила на клиента','Billing street'=>'Улица за фактуриране','Billing address line 2'=>'Адрес за фактуриране, ред 2','Billing town'=>'Населено място за фактуриране','Billing region'=>'Област за фактуриране','Billing postcode'=>'Пощенски код за фактуриране','Billing country'=>'Държава за фактуриране','Company invoice (yes/no)'=>'Фактура на фирма (да/не)','Company name'=>'Име на фирмата','Company town'=>'Населено място на фирмата','Company address'=>'Адрес на фирмата','Buyer (company or person)'=>'Купувач (фирма или лице)','Delivery'=>'Доставка','Recipient'=>'Получател','Recipient phone'=>'Телефон на получателя','Delivery street or office'=>'Улица или офис за доставка','Delivery address line 2'=>'Адрес за доставка, ред 2','Delivery town'=>'Населено място за доставка','Delivery region'=>'Област за доставка','Delivery postcode'=>'Пощенски код за доставка','Delivery country'=>'Държава за доставка','Shipping method'=>'Метод за доставка','Waybill number'=>'Номер на товарителница','Payment'=>'Плащане','Payment method ID'=>'ID на начина на плащане','Transaction ID'=>'ID на транзакцията','Paid (yes/no)'=>'Платена (да/не)','Amounts'=>'Суми','Total'=>'Общо','Total without VAT'=>'Общо без ДДС','VAT'=>'ДДС','Products subtotal'=>'Междинна сума на продуктите','Discount'=>'Отстъпка','Fees'=>'Такси','Refunded'=>'Възстановено','Number of items'=>'Брой артикули','Products (names)'=>'Продукти (имена)','Document number'=>'Номер на документа','Document date'=>'Дата на документа','Invoice date'=>'Дата на фактурата','Product line'=>'Продукт в поръчката','Product ID'=>'ID на продукта','Variation ID'=>'ID на вариацията','Quantity'=>'Количество','Unit price'=>'Единична цена','Line subtotal'=>'Междинна сума на реда','Line total'=>'Общо за реда','Line VAT'=>'ДДС за реда','VAT rate %'=>'Ставка ДДС %','Refund document'=>'Документ за възстановяване','yes'=>'да','no'=>'не','Parcel locker'=>'Автомат за пратки','Total: %1$s | Total vat: %2$s | Returned Total: %3$s'=>'Общо: %1$s | Общо ДДС: %2$s | Общо възстановено: %3$s','The PHP XMLWriter extension is required to create the NRA XML file.'=>'За създаване на XML файла за НАП е нужно PHP разширението XMLWriter.','NRA audit file for %1$s - %2$s'=>'Одиторски файл за НАП за %1$s - %2$s','The audit file (Ordinance N-18) of %2$s for %1$s is attached. It was made by Nashenski Commerce.'=>'Приложен е одиторският файл (Наредба Н-18) на %2$s за %1$s. Създаден е от Нашенски Комерс.','Shipping: %s'=>'Доставка: %s','Empty fields follow TokenForge, for example var(--primary), and change with it.'=>'Празните полета следват TokenForge, например var(--primary), и се променят заедно с него.','Empty fields follow the design tokens of your CSS framework, for example var(--primary).'=>'Празните полета следват дизайн токените на вашата CSS рамка, например var(--primary).','Empty fields follow your theme: its text colour with light borders.'=>'Празните полета следват темата ви: цвета на текста ѝ със светли рамки.','Shipping options look'=>'Вид на опциите за доставка','Any CSS value works: a colour (#1d4ed8), a size (8px) or a token (var(--primary)).'=>'Подходяща е всяка CSS стойност: цвят (#1d4ed8), размер (8px) или токен (var(--primary)).','Layout'=>'Подреждане','Cards: each option in its own box, the chosen one opens its office or address fields'=>'Карти: всяка опция в отделна рамка, избраната отваря полетата за офис или адрес','Plain: keep the look of the theme or builder'=>'Обикновено: запазва вида на темата или конструктора','Show "To an office", "To a parcel locker" or "To your address" under each option'=>'Показване на „До офис“, „До автомат за пратки“ или „До вашия адрес“ под всяка опция','Border of the chosen option, focus ring and buttons.'=>'Рамката на избраната опция, рамката при фокус и бутоните.','Chosen option background'=>'Фон на избраната опция','Option border'=>'Рамка на опцията','Secondary text'=>'Второстепенен текст','Delivery type and office addresses.'=>'Видът доставка и адресите на офисите.','Option corners'=>'Ъгли на опцията','Field border'=>'Рамка на полетата','Search, street and number fields.'=>'Полетата за търсене, улица и номер.','Field background'=>'Фон на полетата','Field corners'=>'Ъгли на полетата','Logo height'=>'Височина на логото','I want an invoice for a company'=>'Искам фактура на фирма','MOL (responsible person)'=>'МОЛ (материално отговорно лице)','Registered town'=>'Населено място по регистрация','Registered address'=>'Адрес по регистрация','Do you want a company invoice?'=>'Искате ли фактура на фирма?','Company'=>'Фирма','(optional)'=>'(незадължително)','The EIK has 9 or 13 digits.'=>'ЕИК има 9 или 13 цифри.','Invalid country code'=>'Невалиден код на държава','Error communicating with the VAT validation server - please try again'=>'Грешка при връзката със сървъра за проверка на ДДС номера. Опитайте отново','You have entered an invalid %1$s (%2$s) for your billing country (%3$s).'=>'Въведохте невалиден %1$s (%2$s) за държавата за фактуриране (%3$s).','You have entered an invalid VAT number (%1$s) for your billing country (%2$s).'=>'Въведохте невалиден ДДС номер (%1$s) за държавата за фактуриране (%2$s).','Street address'=>'Улица и номер','Apartment, suite, unit (address line 2)'=>'Апартамент, офис, етаж (адрес, ред 2)','Town / City'=>'Град','Region / State'=>'Област','Postcode'=>'Пощенски код','Choose an option'=>'Изберете','Order, width and visibility of the billing fields, and your own fields. Show, require and hide apply to the billing and the shipping address in every checkout. The order also applies to the address in the block checkout, where the email always comes first and your own fields appear under it. Width and the place of the email apply to the classic checkout and page builder checkouts that show WooCommerce\'s billing fields; builder checkouts made of single field elements follow the order you placed them in.'=>'Ред, ширина и видимост на полетата за фактуриране и Ваши собствени полета. Показването, задължителността и скриването важат за адреса за фактуриране и за доставка при всеки вид плащане. Редът важи и за адреса при блоковото плащане, където имейлът винаги е пръв, а Вашите полета са под него. Ширината и мястото на имейла важат за класическото плащане и за плащане, създадено с конструктор, което показва полетата за фактуриране на WooCommerce; плащане от отделни полета, създадено с конструктор, следва реда, в който сте ги поставили.','Fields'=>'Полета','Email address'=>'Имейл адрес','Text'=>'Текст','Text area'=>'Текстово поле','List'=>'Списък','Checkbox'=>'Отметка','Number'=>'Номер','Date'=>'Дата','One choice per line'=>'По един избор на ред','Full width'=>'Цяла ширина','Half width'=>'Половин ширина','Position'=>'Позиция','Show'=>'Показване','Add your own field'=>'Добавяне на собствено поле','Use the arrows to change the order. Two half-width fields next to each other share a line. With company invoice fields on, the company name belongs to them.'=>'Сменете реда със стрелките. Две съседни полета с половин ширина са на един ред. Когато полетата за фактура на фирма са включени, името на фирмата е част от тях.','Complete the fields to calculate'=>'Попълнете данните за изчисляване','Free shipping'=>'Безплатна доставка','To your address'=>'До вашия адрес','Search by town, name or address'=>'Търсене по населено място, име или адрес','Change'=>'Промяна','Choose on the map'=>'Избор на картата','Choose an office on the map'=>'Изберете офис на картата','Close'=>'Затваряне','Loading...'=>'Зареждане...','Nothing found. Check the town in the address above.'=>'Нищо не е намерено. Проверете населеното място в адреса по-горе.','No match. Try another word.'=>'Няма съвпадение. Опитайте с друга дума.','Enter your town in the address above to see the list.'=>'Въведете населеното си място в адреса по-горе, за да видите списъка.','Choose it on the map. The price comes from the courier\'s public price list.'=>'Изберете на картата. Цената се изчислява по публичния ценоразпис на куриера.','This is an office. Choose a parcel locker, or pick the office delivery option.'=>'Това е офис. Изберете автомат за пратки или опцията за доставка до офис.','This is a parcel locker. Choose an office, or pick the parcel locker delivery option.'=>'Това е автомат за пратки. Изберете офис или опцията за доставка до автомат.','Start typing the street or quarter'=>'Започнете да пишете улицата или квартала','Street and number'=>'Улица и номер','Note for the courier (optional)'=>'Бележка за куриера (незадължително)','The list could not be loaded. Please try again.'=>'Списъкът не можа да се зареди. Опитайте отново.','Try again'=>'Опитайте отново','bl.'=>'бл.','entr.'=>'вх.','fl.'=>'ет.','ap.'=>'ап.','Transliterate addresses (Cyrillic in Bulgaria, Latin abroad)'=>'Транслитерация на адресите (кирилица в България, латиница в чужбина)','Addresses transliterated.'=>'Адресите са транслитерирани.','Withdraw from contract here'=>'Откажете се от договора тук','Ordered without an account?'=>'Поръчали сте без регистрация?','The full order'=>'Цялата поръчка','Specific items only'=>'Само някои продукти','Withdrawal requested'=>'Подаден отказ','Withdrawal'=>'Отказ','The customer withdrew from the contract on %s. See the "Withdrawal from contract" box.'=>'Клиентът се отказа от договора на %s. Вижте полето „Отказ от договора“.','Withdrawal from contract'=>'Отказ от договора','Submitted'=>'Подаден на','Withdrawing'=>'Отказ от','Additional details'=>'Допълнителна информация','None provided'=>'Няма','The customer received an acknowledgement by email with these details and the date and time of submission.'=>'Клиентът получи по имейл потвърждение с тези данни и датата и часа на подаване.','This withdrawal was sent before Nashenski Commerce kept the submitted details. The date and the choice come from the order note; the full details are in the emails WooCommerce sent to you and to the customer.'=>'Този отказ е подаден, преди Нашенски Комерс да пази подадените данни. Датата и изборът са взети от бележката към поръчката; пълните данни са в имейлите, които WooCommerce изпрати на Вас и на клиента.','Customers can withdraw from an order online, as Directive 2011/83/EU (Article 11a) asks from 19 June 2026: WooCommerce\'s withdrawal form with a "confirm withdrawal" step, a dated acknowledgement email to the customer and an email to you. Its look follows your site; the emails follow WooCommerce > Settings > Emails. Mention the withdrawal function in your terms.'=>'Клиентите могат да се откажат от поръчка онлайн, както изисква Директива 2011/83/ЕС (член 11а) от 19 юни 2026 г.: формулярът за отказ на WooCommerce със стъпка „потвърждавам отказа“, потвърждение с дата и час до клиента и имейл до Вас. Видът му следва сайта Ви, а имейлите следват WooCommerce > Настройки > Имейли. Споменете функцията за отказ в общите си условия.','Needs WooCommerce 11.1 or newer.'=>'Изисква WooCommerce 11.1 или по-нова версия.','Withdrawal function'=>'Функция за отказ','Turn on the withdrawal form and the "Withdraw from contract here" links'=>'Включване на формуляра за отказ и връзките „Откажете се от договора тук“','Link on every page'=>'Връзка на всяка страница','At the bottom of every page'=>'Най-долу на всяка страница','I place it myself (menu, footer template or shortcode)'=>'Поставям я сам (меню, шаблон на футъра или кратък код)','Shortcode for any page or builder: %1$s (add button="yes" for a button). Address for menus: %2$s'=>'Кратък код за всяка страница или конструктор: %1$s (добавете button="yes" за бутон). Адрес за менюта: %2$s','Withdrawal period (days)'=>'Срок за отказ (дни)','The link shows on an order (My Account, order page, order emails) until this many days after the order is completed. The form itself is always open.'=>'Връзката се показва при поръчката (Моят профил, страницата на поръчката, имейлите) до толкова дни след завършването ѝ. Самият формуляр е винаги достъпен.','On a payment account'=>'По платежна сметка','Card'=>'С карта','Released under Art. 3 payment without PPP'=>'Освободено по чл. 3, плащане без ППП','Virtual POS terminal'=>'Виртуален ПОС терминал','Cash on delivery with PPP'=>'Наложен платеж с ППП','Payment service provider'=>'Доставчик на платежни услуги','Reflected with receipt'=>'Отразено с касова бележка','Standard'=>'Стандартна','Review only'=>'Само преглед','This page has expired. Reload it and try again.'=>'Страницата е изтекла. Презаредете я и опитайте отново.','You cannot create labels.'=>'Не можете да създавате товарителници.','Label created.'=>'Товарителницата е създадена.','Label updated.'=>'Товарителницата е обновена.','Label deleted.'=>'Товарителницата е изтрита.','Label number: %s.'=>'Номер на товарителница: %s.','Date of tax. event'=>'Дата на дан. събитие','Due date'=>'Срок за плащане','Place of transaction'=>'Място на сделката','Order Number'=>'Номер на поръчката','Qty'=>'Кол.','Vat'=>'ДДС','Total amount'=>'Обща сума','EIK: %s'=>'ЕИК: %s','VAT Number: %s'=>'ДДС номер: %s','MOL: %s'=>'МОЛ: %s','Phone: %s'=>'Телефон: %s','E-mail: %s'=>'Имейл: %s','Bank account'=>'Банкова сметка','Compiled by'=>'Съставил','Received'=>'Получил','Bank name'=>'Банка','Credit Notice - Original'=>'Кредитно известие - Оригинал','To invoice №'=>'Към фактура №','Credit Notice - Copy'=>'Кредитно известие - Копие','Sale Invoice - Original'=>'Фактура - Оригинал','Sale Invoice - Copy'=>'Фактура - Копие','Order - Original'=>'Документ за продажба - Оригинал','Refunded Order - Original'=>'Документ за възстановяване - Оригинал','Total due'=>'Сума за плащане','2 October 2026 (month in the language of the document)'=>'2 октомври 2026 (месецът на езика на документа)','Billing from'=>'Доставчик','Billing to'=>'Получател','Page %1$s of %2$s'=>'Страница %1$s от %2$s','Amount due'=>'Сума за плащане','The invoice has been issued on the basis of Article 113, paragraph 9 of the Bulgarian VAT Act.'=>'Фактурата е издадена на основание чл. 113, ал. 9 от ЗДДС.','Nashenski Commerce - Please review the options and save them again from "%s".'=>'Нашенски Комерс: прегледайте настройките и ги запазете отново от „%s“.','The file was downloaded.'=>'Файлът е изтеглен.','Built-in prices restored. Save to keep them.'=>'Вградените цени са възстановени. Запазете, за да ги задържите.','Your prices match the courier website.'=>'Цените ви съвпадат със сайта на куриера.','The courier website has different prices:'=>'Сайтът на куриера има различни цени:','Website'=>'Сайт','Use these prices'=>'Използване на тези цени','New prices filled in. Check them and save.'=>'Новите цени са попълнени. Проверете ги и запазете.','There is no public price list for this courier.'=>'За този куриер няма публичен ценоразпис.','The courier website did not let Nashenski Commerce read the price list (%s). Open it, compare and edit the prices by hand.'=>'Сайтът на куриера не позволи на Нашенски Комерс да прочете ценоразписа (%s). Отворете го, сравнете и редактирайте цените ръчно.','The price list on the courier website has changed and could not be read safely. Your prices were not changed.'=>'Ценоразписът на сайта на куриера е променен и не може да се прочете надеждно. Цените ви не са променени.','Extra surcharge %'=>'Допълнителна такса %','Cash on delivery %'=>'Наложен платеж %','Cash on delivery minimum'=>'Минимум за наложен платеж','Up to %1$s kg, %2$s'=>'До %1$s кг, %2$s','Unknown courier.'=>'Непознат куриер.','Possibility that the shipment will not be picked up: %s'=>'Вероятност пратката да не бъде потърсена: %s','Connectix did not answer. Check the token and the environment in Customer checks.'=>'Connectix не отговори. Проверете токена и средата в Проверки на клиенти.','Error: %s'=>'Грешка: %s','nekorekten.com has %d report about this phone number.'=>'nekorekten.com има %d сигнал за този телефонен номер.' . "\0" . 'nekorekten.com има %d сигнала за този телефонен номер.','nekorekten.com did not answer. Check the API key in the settings.'=>'nekorekten.com не отговори. Проверете API ключа в настройките.','No reports were found for this phone number.'=>'Няма сигнали за този телефонен номер.','%d report was found for this phone number.'=>'Открит е %d сигнал за този телефонен номер.' . "\0" . 'Открити са %d сигнала за този телефонен номер.','This client has %s%% undelivered shipments.'=>'Този клиент има %s%% непотърсени пратки.','No data found for this phone number.'=>'Няма данни за този телефонен номер.','This client has %s%% undelivered shipments, which is below the set threshold.'=>'Този клиент има %s%% непотърсени пратки, което е под зададения праг.','Total shipments: %s'=>'Общо пратки: %s','Delivered shipments: %1$s ( %2$s%% )'=>'Доставени пратки: %1$s ( %2$s%% )','Undelivered shipments: %1$s ( %2$s%% )'=>'Недоставени пратки: %1$s ( %2$s%% )','Reports'=>'Сигнали','Refresh data'=>'Обновяване на данните','Not checked: turned on without an API key or token. Add it in %s, or turn the service off there.'=>'Не е проверено: включено е без API ключ или токен. Добавете го в %s или изключете услугата оттам.','Customer has reports for refused parcels. See the Reports box.'=>'Клиентът има сигнали за отказани пратки. Вижте полето „Сигнали“.','No reports for this customer.'=>'Няма сигнали за този клиент.','Not checked'=>'Не е проверено','No reports'=>'Няма сигнали','%d report'=>'%d сигнал' . "\0" . '%d сигнала','Create waybill'=>'Създай товарителница','Request a courier (Econt, Speedy)'=>'Заяви куриер (Еконт, Спиди)','Check the shipment now'=>'Провери пратката сега','Do not change'=>'Без промяна','Waybills and order statuses'=>'Товарителници и статуси на поръчките','For every courier you use. On each order, and for many orders at once in the orders list, you also get "Create waybill", "Request a courier" and "Check the shipment now".'=>'За всеки куриер, който използвате. За всяка поръчка, както и за много поръчки наведнъж в списъка с поръчки, имате и „Създай товарителница“, „Заяви куриер“ и „Провери пратката сега“.','Order number on the waybill'=>'Номер на поръчката в товарителницата','Econt and Speedy get it in their reference field, BOX NOW on the label, Pigeon Express in the note for the courier and CVC in front of the contents.'=>'Еконт и Спиди го получават в полето си за референция, BOX NOW на етикета, Pigeon Express в бележката към куриера, а CVC пред съдържанието.','When the parcel is delivered'=>'Когато пратката е доставена','When the parcel goes back to you'=>'Когато пратката се връща при Вас','Refused by the customer or returned. Orders that are processing or on hold and have an Econt, Speedy, BOX NOW or CVC waybill are checked every hour, and each change is noted on the order. Pigeon Express does not publish its statuses yet.'=>'Отказана от клиента или върната. Поръчките в обработка или задържани, които имат товарителница на Еконт, Спиди, BOX NOW или CVC, се проверяват всеки час и всяка промяна се записва в поръчката. Pigeon Express все още не публикува статусите си.','Order %s'=>'Поръчка %s','Track your parcel:'=>'Проследете пратката си:','This order has no waybill yet.'=>'Тази поръчка още няма товарителница.','The shipment status can only be read for Econt, Speedy, BOX NOW and CVC, with their login.'=>'Статусът на пратката може да се прочете само за Еконт, Спиди, BOX NOW и CVC, с техния вход.','The courier delivered parcel %s.'=>'Куриерът достави пратка %s.','Parcel %s is going back to you (refused or returned).'=>'Пратка %s се връща при Вас (отказана или върната).','delivered'=>'доставена','going back to you'=>'връща се при Вас','still on its way'=>'все още е на път','Order %1$s: %2$s'=>'Поръчка %1$s: %2$s','already has waybill %s'=>'вече има товарителница %s','not sent with a courier that has a login'=>'не е с куриер, за който има вход','could not be sent: %s'=>'не може да се изпрати: %s','waybill %s created'=>'създадена е товарителница %s','the courier did not create the waybill; open the order to see why'=>'куриерът не създаде товарителница; отворете поръчката, за да видите защо','Order %s: only Econt and Speedy waybills can get a courier request here.'=>'Поръчка %s: тук може да се заяви куриер само за товарителници на Еконт и Спиди.','Courier request for waybill %1$s failed: %2$s'=>'Заявката за куриер за товарителница %1$s не успя: %2$s','Courier requested for waybill %s.'=>'Заявен е куриер за товарителница %s.','%1$s, waybills %2$s: %3$s'=>'%1$s, товарителници %2$s: %3$s','courier requested'=>'куриерът е заявен','you send from an Econt office, so no courier comes to you'=>'изпращате от офис на Еконт, затова при Вас не идва куриер','Econt did not accept the request.'=>'Еконт не прие заявката.','Speedy did not accept the request.'=>'Спиди не прие заявката.','Nashenski Commerce - BOX NOW'=>'Нашенски Комерс - BOX NOW','Enables BOX NOW delivery.'=>'Включва доставка с BOX NOW.','Title'=>'Заглавие','This controls the title which the user sees during checkout.'=>'Заглавието, което клиентът вижда при плащане.','Please choose a automat.'=>'Изберете автомат.','Label number: %1$s. %2$s'=>'Номер на товарителница: %1$s. %2$s','Track your order.'=>'Проследете поръчката си.','Nashenski Commerce - CVC'=>'Нашенски Комерс - CVC','Enables CVC delivery and automatically calculate shipping price.'=>'Включва доставка с CVC и автоматично изчисляване на цената за доставка.','Delivery Type'=>'Вид доставка','Saturday Delivery'=>'Доставка в събота','Saturday delivery/pickup.'=>'Доставка/вземане в събота.','SMS notification'=>'SMS известие','Send customer notification for delivery.'=>'Изпращане на известие до клиента за доставката.','Enter a fixed price that will be payed by you, and will be included in the order.'=>'Въведете фиксирана цена, която плащате вие и която се включва в поръчката.','Calculation failed. Please try again.'=>'Изчисляването не успя. Опитайте отново.','CVC - %s'=>'CVC - %s','Please choose delivery option!'=>'Изберете вариант за доставка!','Nashenski Commerce - Econt'=>'Нашенски Комерс - Еконт','Enables econt delivery and automatically calculate shipping price.'=>'Включва доставка с Еконт и автоматично изчисляване на цената за доставка.','Maximum price payed by the client'=>'Максимална цена, плащана от клиента','Enter a fixed price that the users will pay. The remaining will be payed by you.'=>'Въведете фиксирана цена, която плащат клиентите. Остатъкът плащате вие.','Can be used only in Bulgaria'=>'Може да се използва само в България','Econt - '=>'Еконт - ','Please choose a office.'=>'Изберете офис.','Please choose address.'=>'Изберете адрес.','No automats were found at %s.'=>'Няма автомати в %s.','No offices were found at %s.'=>'Няма офиси в %s.','Please select region.'=>'Изберете област.','Please enter a city.'=>'Въведете населено място.','%1$s is not found in %2$s region.'=>'%1$s не е намерено в област %2$s.','No lockers were found at %s.'=>'Няма шкафчета в %s.','Nashenski Commerce - Pigeon Express'=>'Нашенски Комерс - Pigeon Express','Enables Pigeon Express delivery and automatically calculate shipping price.'=>'Включва доставка с Pigeon Express и автоматично изчисляване на цената за доставка.','APS'=>'Автомат','Enter a fixed price that will be payed by the client, and will be included in the COD.'=>'Въведете фиксирана цена, която плаща клиентът и която се включва в наложения платеж.','An error occurred while calculating the shipping price. Please try again later.'=>'Възникна грешка при изчисляването на цената за доставка. Опитайте отново по-късно.','Pigeon Express - '=>'Pigeon Express - ','Please choose an office.'=>'Изберете офис.','Please choose a locker.'=>'Изберете шкафче.','Please choose an address.'=>'Изберете адрес.','Nashenski Commerce - Speedy'=>'Нашенски Комерс - Спиди','Enables Speedy delivery and automatically calculate shipping price.'=>'Включва доставка със Спиди и автоматично изчисляване на цената за доставка.','Speedy - %s'=>'Спиди - %s','Nashenski Commerce requires PHP version %1$s+ and WP version %2$s+, plugin is currently NOT RUNNING.'=>'Нашенски Комерс изисква PHP версия %1$s+ и WP версия %2$s+; разширението в момента НЕ РАБОТИ.','Nashenski Commerce is paused: please deactivate Bulgarisation for WooCommerce first. Your settings and orders can be imported afterwards.'=>'Нашенски Комерс е на пауза: първо деактивирайте Bulgarisation for WooCommerce. След това можете да импортирате настройките и поръчките си.','Nashenski Commerce - Please enable WooCommerce first.'=>'Нашенски Комерс: първо включете WooCommerce.','Please run `composer install` in the plugin folder `nashenski-commerce`'=>'Изпълнете `composer install` в папката на разширението `nashenski-commerce`','Shipping to %s.'=>'Доставка до %s.','Change address'=>'Промяна на адреса','Shipping options will be updated during checkout.'=>'Опциите за доставка ще се обновят при плащане.','Shipping costs are calculated during checkout.'=>'Цената за доставка се изчислява при плащане.','Enter your address to view shipping options.'=>'Въведете адреса си, за да видите опциите за доставка.','There are no shipping options available. Please ensure that your address has been entered correctly, or contact us if you need any help.'=>'Няма налични опции за доставка. Проверете дали адресът е въведен правилно или се свържете с нас, ако имате нужда от помощ.','No shipping options were found for %s.'=>'Не са открити опции за доставка до %s.','Enter a different address'=>'Въведете друг адрес','Everything a WooCommerce store needs to sell in Bulgaria: Econt, Speedy, BOX NOW, CVC and Pigeon shipping, invoices, and the light regime of Ordinance N-18.'=>'Всичко, от което магазинът с WooCommerce има нужда, за да продава в България: доставка с Еконт, Спиди, BOX NOW, CVC и Pigeon, фактури и облекченият режим по Наредба Н-18.','PristaDigital'=>'PristaDigital','The document was not found or you do not have access to it.'=>'Документът не е намерен или нямате достъп до него.','Cash on delivery is not available for this order. Please choose another payment method.'=>'Наложеният платеж не е възможен за тази поръчка. Моля, изберете друг начин на плащане.','The payment method changed after the shipping price was calculated. Please check the updated total and place the order again.'=>'Начинът на плащане беше променен след изчисляването на цената за доставка. Моля, проверете новата обща сума и направете поръчката отново.']];